company_audit_summary	 SELECT company_id,\n    date("timestamp") AS date,\n    action,\n    count(*) AS count,\n    count(*) FILTER (WHERE severity = 'critical'::text) AS critical_count\n   FROM audit_log\n  WHERE "timestamp" > (now() - '30 days'::interval)\n  GROUP BY company_id, (date("timestamp")), action;	2026-05-18 16:11:57.530873+00
vw_horarios_completos	 SELECT id,\n    company_id,\n    number AS numero,\n    name AS nome,\n    description AS descricao,\n    start_time AS hora_entrada,\n    end_time AS hora_saida,\n    break_start_time AS intervalo_inicio,\n    break_end_time AS intervalo_fim,\n    break_duration,\n    break_minutes,\n    tolerance_minutes,\n    tolerancia_entrada,\n    tolerancia_saida,\n    carga_horaria_minutos,\n    concat(lpad((carga_horaria_minutos / 60)::text, 2, '0'::text), ':', lpad((carga_horaria_minutos % 60)::text, 2, '0'::text)) AS carga_horaria_formatada,\n    shift_type AS tipo_jornada,\n    is_night_shift AS turno_noturno,\n    ativo,\n    config,\n    created_at,\n    updated_at\n   FROM work_shifts ws\n  WHERE ativo = true OR ativo IS NULL;	2026-05-18 16:11:57.530873+00
vw_escalas_completas	 SELECT s.id,\n    s.company_id,\n    s.name AS nome,\n    s.tipo,\n    s.dias_trabalho,\n    s.dias_folga,\n    s.descricao,\n    s.days AS dias_semana,\n    s.shift_id AS horario_padrao_id,\n    ws.name AS horario_padrao_nome,\n    s.ativo,\n    s.created_at,\n    s.updated_at,\n    COALESCE(( SELECT jsonb_agg(jsonb_build_object('dia_semana', ed.dia_semana, 'tipo', ed.tipo, 'horario_id', ed.horario_id, 'horario_nome', wsd.name) ORDER BY ed.dia_semana) AS jsonb_agg\n           FROM escala_dias ed\n             LEFT JOIN work_shifts wsd ON wsd.id = ed.horario_id\n          WHERE ed.escala_id = s.id), '[]'::jsonb) AS dias_detalhados\n   FROM schedules s\n     LEFT JOIN work_shifts ws ON ws.id = s.shift_id\n  WHERE s.ativo = true OR s.ativo IS NULL;	2026-05-18 16:11:57.530873+00
suspicious_login_attempts	 SELECT identifier,\n    ip_address,\n    attempt_count,\n    first_attempt_at,\n    last_attempt_at,\n    locked_until\n   FROM login_attempts\n  WHERE attempt_count >= 3 AND last_attempt_at > (now() - '01:00:00'::interval)\n  ORDER BY attempt_count DESC, last_attempt_at DESC;	2026-05-18 16:11:57.530873+00
v_funcionarios_relatorio	 SELECT e.id,\n    e.company_id,\n    COALESCE(e.nome, u.nome, u.email) AS nome,\n    u.numero_folha,\n    u.numero_identificador,\n    u.admissao,\n    u.demissao,\n        CASE\n            WHEN u.demissao IS NOT NULL THEN 'DEMITIDO'::text\n            WHEN e.status = 'inactive'::text THEN 'INATIVO'::text\n            ELSE 'ATIVO'::text\n        END AS situacao,\n    d.name AS departamento,\n    e.cargo AS funcao,\n    ws.description AS horario,\n    COALESCE(c.nome, c.name) AS empresa,\n    md.name AS motivo_demissao\n   FROM employees e\n     LEFT JOIN users u ON u.id = e.id\n     LEFT JOIN departments d ON d.id = e.department_id\n     LEFT JOIN work_shifts ws ON ws.id = e.schedule_id\n     LEFT JOIN companies c ON c.id = e.company_id\n     LEFT JOIN motivo_demissao md ON md.id = u.motivo_demissao_id;	2026-05-18 16:11:57.530873+00
v_rep_punch_logs_pendentes_espelho	 SELECT id,\n    company_id,\n    rep_device_id,\n    data_hora,\n    tipo_marcacao,\n    nsr,\n    pis,\n    cpf,\n    matricula,\n    nome_funcionario,\n    time_record_id,\n    created_at,\n    (EXISTS ( SELECT 1\n           FROM users u\n          WHERE u.company_id = l.company_id AND (rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)) IS NOT NULL AND rep_afd_canonical_11_digits(COALESCE(u.pis_pasep, ''::text)) = rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)) OR rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)) IS NOT NULL AND rep_matricula_matches_user_fields(rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)), u.numero_folha, u.numero_identificador) OR rep_matricula_matches_user_fields(COALESCE(NULLIF(TRIM(BOTH FROM l.matricula), ''::text), rep_derive_matricula_from_afd_11(COALESCE(l.pis, l.cpf, ''::text))), u.numero_folha, u.numero_identificador) OR rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)) IS NOT NULL AND rep_afd_canonical_11_digits(COALESCE(u.cpf, ''::text)) = rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)) OR rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)) IS NOT NULL AND rep_matricula_matches_user_fields(rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)), u.numero_folha, u.numero_identificador)))) AS cadastro_compativel\n   FROM rep_punch_logs l\n  WHERE time_record_id IS NULL;	2026-05-18 16:11:57.530873+00
work_schedules	 SELECT s.id,\n    s.company_id,\n    s.name,\n    COALESCE(ws.start_time::text, '08:00'::text) AS start_time,\n    COALESCE(ws.end_time::text, '17:00'::text) AS end_time,\n    COALESCE(ws.break_start_time::text, ws.start_time::text) AS break_start,\n    COALESCE(ws.break_end_time::text, ws.end_time::text) AS break_end,\n    COALESCE(ws.tolerance_minutes, 0) AS tolerance_minutes,\n    COALESCE(EXTRACT(epoch FROM ws.end_time - ws.start_time) / 3600.0 -\n        CASE\n            WHEN ws.break_start_time IS NOT NULL AND ws.break_end_time IS NOT NULL THEN EXTRACT(epoch FROM ws.break_end_time - ws.break_start_time) / 3600.0\n            ELSE 0::numeric\n        END, 8::numeric) AS daily_hours,\n    ( SELECT count(*)::integer AS count\n           FROM unnest(COALESCE(s.days, ARRAY[]::integer[])) d(d)\n          WHERE d.d >= 1 AND d.d <= 7) AS work_days_count\n   FROM schedules s\n     LEFT JOIN work_shifts ws ON ws.id = s.shift_id;	2026-05-18 16:11:57.530873+00
time_entries	 WITH tr AS (\n         SELECT r.id,\n            r.user_id AS employee_id,\n            r.company_id,\n            (COALESCE(r."timestamp", r.created_at) AT TIME ZONE 'America/Sao_Paulo'::text)::date AS work_date,\n            to_char((COALESCE(r."timestamp", r.created_at) AT TIME ZONE 'America/Sao_Paulo'::text), 'HH24:MI'::text) AS hhmm,\n                CASE lower(TRIM(BOTH FROM COALESCE(r.type, ''::text)))\n                    WHEN 'entrada'::text THEN 'entrada'::text\n                    WHEN 'saida'::text THEN 'saida'::text\n                    WHEN 'sa├¡da'::text THEN 'saida'::text\n                    WHEN 'pausa'::text THEN 'intervalo_saida'::text\n                    WHEN 'intervalo_saida'::text THEN 'intervalo_saida'::text\n                    WHEN 'intervalo_volta'::text THEN 'intervalo_volta'::text\n                    ELSE lower(TRIM(BOTH FROM COALESCE(r.type, ''::text)))\n                END AS norm_type,\n            COALESCE(r."timestamp", r.created_at) AS instant_ref\n           FROM time_records r\n        ), agg AS (\n         SELECT tr.employee_id,\n            tr.company_id,\n            tr.work_date,\n            min(\n                CASE\n                    WHEN tr.norm_type = 'entrada'::text THEN tr.hhmm\n                    ELSE NULL::text\n                END) AS entrada,\n            min(\n                CASE\n                    WHEN tr.norm_type = 'intervalo_saida'::text THEN tr.hhmm\n                    ELSE NULL::text\n                END) AS saida_intervalo,\n            min(\n                CASE\n                    WHEN tr.norm_type = 'intervalo_volta'::text THEN tr.hhmm\n                    ELSE NULL::text\n                END) AS volta_intervalo,\n            max(\n                CASE\n                    WHEN tr.norm_type = 'saida'::text THEN tr.hhmm\n                    ELSE NULL::text\n                END) AS saida_final,\n            count(*) FILTER (WHERE tr.norm_type <> ALL (ARRAY['entrada'::text, 'intervalo_saida'::text, 'intervalo_volta'::text, 'saida'::text]))::integer AS inconsistency_count\n           FROM tr\n          GROUP BY tr.employee_id, tr.company_id, tr.work_date\n        )\n SELECT md5((((employee_id || '|'::text) || company_id) || '|'::text) || work_date::text) AS id,\n    employee_id,\n    company_id,\n    work_date,\n    entrada,\n    saida_intervalo,\n    volta_intervalo,\n    saida_final,\n        CASE\n            WHEN entrada IS NULL OR saida_final IS NULL THEN 0\n            ELSE GREATEST(0, split_part(saida_final, ':'::text, 1)::integer * 60 + split_part(saida_final, ':'::text, 2)::integer - (split_part(entrada, ':'::text, 1)::integer * 60 + split_part(entrada, ':'::text, 2)::integer) -\n            CASE\n                WHEN saida_intervalo IS NOT NULL AND volta_intervalo IS NOT NULL THEN GREATEST(0, split_part(volta_intervalo, ':'::text, 1)::integer * 60 + split_part(volta_intervalo, ':'::text, 2)::integer - (split_part(saida_intervalo, ':'::text, 1)::integer * 60 + split_part(saida_intervalo, ':'::text, 2)::integer))\n                ELSE 0\n            END)\n        END AS worked_minutes,\n    inconsistency_count\n   FROM agg;	2026-05-18 16:11:57.530873+00
