--
-- Name: _compute_geo_snapshot_checksum(double precision, double precision, double precision, timestamp with time zone, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._compute_geo_snapshot_checksum(p_lat double precision, p_lng double precision, p_acc double precision, p_captured timestamp with time zone, p_state_ver bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT md5(
    concat_ws('|',
      COALESCE(p_lat::text, ''),
      COALESCE(p_lng::text, ''),
      COALESCE(p_acc::text, ''),
      CASE
        WHEN p_captured IS NULL THEN ''
        ELSE to_char(p_captured AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      COALESCE(p_state_ver::text, '0')
    )
  );
$$;


