--
-- Name: _cos_source_from_time_record(public.time_records, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._cos_source_from_time_record(r public.time_records, tg_op text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF tg_op = 'INSERT' THEN
    IF public._time_record_should_hide_gps(r) THEN
      RETURN 'rep_import';
    END IF;
    RETURN 'time_record_insert';
  END IF;
  IF COALESCE(r.is_manual, false)
    OR COALESCE(lower(r.method), '') IN ('admin', 'manual')
    OR COALESCE(lower(r.method), '') LIKE '%manual%' THEN
    RETURN 'manual_adjustment';
  END IF;
  RETURN 'reconciliation';
END;
$$;


