--
-- Name: _normalize_cos_state_source(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._normalize_cos_state_source(p_src text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  s TEXT := lower(trim(COALESCE(p_src, '')));
BEGIN
  IF s IN (
    'realtime',
    'time_record_insert',
    'rep_import',
    'replay',
    'reconciliation',
    'manual_adjustment',
    'migration',
    'recovery'
  ) THEN
    RETURN s;
  END IF;
  IF s IN ('time_records_insert', 'time_record_insert') THEN
    RETURN 'time_record_insert';
  END IF;
  IF s IN ('time_records', 'time_records_update', 'time_records_update_old') THEN
    RETURN 'reconciliation';
  END IF;
  IF s IN ('migration_seed') THEN
    RETURN 'migration';
  END IF;
  IF s IN ('rpc', 'client_rpc') THEN
    RETURN 'replay';
  END IF;
  IF s IN ('operational_replay') THEN
    RETURN 'recovery';
  END IF;
  RETURN 'reconciliation';
END;
$$;


ALTER FUNCTION public._normalize_cos_state_source(p_src text) OWNER TO postgres;

--
-- Name: _operational_status_from_punch_type(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._operational_status_from_punch_type(p_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE public._norm_punch_type_sql(p_type)
    WHEN 'entrada' THEN 'WORKING'
    WHEN 'pausa' THEN 'BREAK'
    WHEN 'intervalo_saida' THEN 'LUNCH'
    WHEN 'saida' THEN 'CLOSED'
    WHEN 'intervalo saida' THEN 'LUNCH'
    ELSE 'OFF_DUTY'
  END;
$$;


ALTER FUNCTION public._operational_status_from_punch_type(p_type text) OWNER TO postgres;

--
-- Name: _pwd_add_company_guard(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._pwd_add_company_guard(p_table text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_constraint text := 'chk_' || p_table || '_company_id_required';
BEGIN
  IF NOT public._pwd_table_exists(p_table) THEN
    RETURN;
  END IF;

  IF NOT public._pwd_column_exists(p_table, 'company_id') THEN
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN company_id text', p_table);
  END IF;

  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%I_company_id ON public.%I(company_id)', p_table, p_table);

  IF NOT EXISTS (
    SELECT 1
      FROM pg_constraint
     WHERE conrelid = format('public.%I', p_table)::regclass
       AND conname = v_constraint
  ) THEN
    EXECUTE format(
      'ALTER TABLE public.%I ADD CONSTRAINT %I CHECK (company_id IS NOT NULL AND btrim(company_id::text) <> '''') NOT VALID',
      p_table,
      v_constraint
    );
  END IF;
END;
$$;


ALTER FUNCTION public._pwd_add_company_guard(p_table text) OWNER TO postgres;

