-- Name: _time_record_should_hide_gps(public.time_records); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._time_record_should_hide_gps(tr public.time_records) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(tr.origin, '') = 'rep'
    OR COALESCE(tr.source, '') ILIKE 'rep'
    OR COALESCE(tr.source, '') = 'clock'
    OR COALESCE(tr.method, '') ILIKE 'rep';
$$;


