--
-- Name: add_hours(uuid, text, numeric, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_hours(p_employee_id uuid, p_company_id text, p_hours numeric, p_date date DEFAULT CURRENT_DATE, p_source text DEFAULT 'manual_credit'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev NUMERIC := 0;
  v_new NUMERIC := 0;
BEGIN
  SELECT COALESCE(balance, 0) INTO v_prev
  FROM public.bank_hours
  WHERE employee_id = p_employee_id AND company_id = p_company_id
  ORDER BY date DESC, created_at DESC
  LIMIT 1;

  v_new := COALESCE(v_prev, 0) + GREATEST(COALESCE(p_hours, 0), 0);

    employee_id, company_id, date, hours_added, hours_removed, balance, source, created_at
  ) VALUES (
    p_employee_id, p_company_id, COALESCE(p_date, CURRENT_DATE),
    GREATEST(COALESCE(p_hours, 0), 0), 0, v_new, p_source, NOW()
  );

  RETURN jsonb_build_object('success', true, 'previous_balance', v_prev, 'balance', v_new);
END;
$$;


ALTER FUNCTION public.add_hours(p_employee_id uuid, p_company_id text, p_hours numeric, p_date date, p_source text) OWNER TO postgres;

--
-- Name: anonymize_user(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.anonymize_user(p_user_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_anonymized_id TEXT;
BEGIN
  SELECT * INTO v_user FROM public.users WHERE id = p_user_id LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'USER_NOT_FOUND');
  END IF;

  v_anonymized_id := 'anon_' || left(replace(p_user_id::text, '-', ''), 12);

  UPDATE public.users
  SET
    nome = 'ANONIMIZADO',
    email = v_anonymized_id || '@removed.local',
    cpf = NULL,
    pis_pasep = NULL,
    numero_identificador = NULL,
    numero_folha = NULL,
    ctps = NULL,
    observacoes = NULL,
    phone = NULL,
    avatar = NULL,
    preferences = '{}'::jsonb,
    employee_config = '{}'::jsonb,
    data_classification = 'technical',
    invisivel = true,
    status = 'inactive',
    updated_at = NOW()
  WHERE id = p_user_id;

  IF EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'employee_biometrics'
  ) THEN
    DELETE FROM public.employee_biometrics WHERE employee_id = p_user_id;
  END IF;

  IF p_request_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'data_deletion_requests'
  ) THEN
    UPDATE public.data_deletion_requests
    SET
      status = 'anonymized',
      completed_at = NOW(),
      anonymized_user_id = v_anonymized_id
    WHERE id = p_request_id;
  END IF;

  UPDATE public.rep_punch_logs
  SET
    pis = NULL,
    cpf = NULL,
    matricula = NULL,
    nome_funcionario = 'ANONIMIZADO',
    resolved_user_id = NULL,
    anonymized_at = COALESCE(anonymized_at, NOW()),
    raw_data = COALESCE(raw_data, '{}'::jsonb) || jsonb_build_object('anonymized', true, 'anonymized_at', NOW())
  WHERE company_id = v_user.company_id::text
    AND (
      resolved_user_id = p_user_id::text
      OR (v_user.pis_pasep IS NOT NULL AND pis = v_user.pis_pasep)
      OR (v_user.cpf IS NOT NULL AND cpf = v_user.cpf)
      OR (v_user.numero_identificador IS NOT NULL AND matricula = v_user.numero_identificador)
    );

    id, user_id, company_id, action, entity, entity_id, severity, details, metadata, created_at, "timestamp"
  ) VALUES (
    gen_random_uuid(),
    COALESCE(p_performed_by::text, NULL),
    v_user.company_id::text,
    'LGPD_ANONYMIZE_USER',
    'users',
    p_user_id,
    'SECURITY',
    jsonb_build_object('target_user_id', p_user_id, 'request_id', p_request_id),
    jsonb_build_object('target_user_id', p_user_id, 'anonymized_id', v_anonymized_id),
    NOW(),
    NOW()
  );

  RETURN jsonb_build_object('success', true, 'user_id', p_user_id, 'anonymized_id', v_anonymized_id);
END;
$$;


ALTER FUNCTION public.anonymize_user(p_user_id uuid, p_performed_by uuid, p_request_id uuid) OWNER TO postgres;

