--

CREATE FUNCTION public.backfill_punches_to_time_records(p_limit integer DEFAULT 5000) RETURNS TABLE(total_selected integer, inserted_count integer, already_exists_count integer, invalid_identity_count integer, tenant_mismatch_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  r record;
  v_result jsonb;
  v_selected integer := 0;
  v_inserted integer := 0;
  v_already integer := 0;
  v_invalid integer := 0;
  v_tenant integer := 0;
BEGIN
  FOR r IN
    WITH punch_norm AS (
      SELECT
        p.id,
        COALESCE(
          public.punches_try_uuid(to_jsonb(p)->>'user_id'),
          public.punches_try_uuid(to_jsonb(p)->'payload'->>'user_id'),
          public.punches_try_uuid(to_jsonb(p)->'payload'->>'userId'),
          public.punches_try_uuid(to_jsonb(p)->'raw_data'->>'user_id'),
          public.punches_try_uuid(to_jsonb(p)->'raw_data'->>'userId'),
          public.punches_try_uuid(p.employee_id)
        ) AS user_uuid,
        COALESCE(
          public.punches_try_uuid(to_jsonb(p)->>'company_id'),
          public.punches_try_uuid(to_jsonb(p)->'payload'->>'company_id'),
          public.punches_try_uuid(to_jsonb(p)->'payload'->>'companyId'),
          public.punches_try_uuid(to_jsonb(p)->'raw_data'->>'company_id'),
          public.punches_try_uuid(to_jsonb(p)->'raw_data'->>'companyId')
        ) AS company_uuid,
        COALESCE(
          public.punches_try_timestamptz(to_jsonb(p)->>'timestamp'),
          public.punches_try_timestamptz(to_jsonb(p)->'payload'->>'timestamp'),
          public.punches_try_timestamptz(to_jsonb(p)->'raw_data'->>'timestamp'),
          p.created_at
        ) AS event_ts,
        p.created_at
      FROM public.punches p
    )
    SELECT pn.id
    FROM punch_norm pn
    WHERE pn.user_uuid IS NOT NULL
      AND pn.company_uuid IS NOT NULL
      AND pn.event_ts IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.time_records tr
        WHERE tr.user_id::text = pn.user_uuid::text
          AND tr.company_id::text = pn.company_uuid::text
          AND abs(extract(epoch FROM (tr."timestamp" - pn.event_ts))) <= 2
      )
    ORDER BY pn.created_at ASC NULLS FIRST, pn.id
    LIMIT GREATEST(COALESCE(p_limit, 5000), 1)
  LOOP
    v_selected := v_selected + 1;
    v_result := public.promote_punch_to_time_record(r.id);

    CASE COALESCE(v_result->>'status', '')
      WHEN 'inserted' THEN v_inserted := v_inserted + 1;
      WHEN 'already_exists' THEN v_already := v_already + 1;
      WHEN 'already_exists_nearby' THEN v_already := v_already + 1;
      WHEN 'invalid_identity' THEN v_invalid := v_invalid + 1;
      WHEN 'tenant_mismatch' THEN v_tenant := v_tenant + 1;
      ELSE NULL;
    END CASE;
  END LOOP;

  RETURN QUERY
  SELECT v_selected, v_inserted, v_already, v_invalid, v_tenant;
END;
$$;


ALTER FUNCTION public.backfill_punches_to_time_records(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION backfill_punches_to_time_records(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.backfill_punches_to_time_records(p_limit integer) IS 'Backfill idempotente de punches sem time_record correspondente, independentemente de sent_at.';


--
-- Name: calcular_carga_horaria_minutos(time without time zone, time without time zone, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcular_carga_horaria_minutos(p_start_time time without time zone, p_end_time time without time zone, p_break_start time without time zone, p_break_end time without time zone) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_total_minutos INTEGER;
  v_intervalo_minutos INTEGER := 0;
BEGIN
  IF p_start_time IS NULL OR p_end_time IS NULL THEN
    RETURN 0;
  END IF;
  
  -- Calcular tempo total (considerando turno noturno)
  IF p_end_time > p_start_time THEN
    v_total_minutos := EXTRACT(EPOCH FROM (p_end_time - p_start_time)) / 60;
  ELSE
    -- Turno noturno: passa da meia-noite
    v_total_minutos := EXTRACT(EPOCH FROM ('24:00:00'::TIME - p_start_time + p_end_time)) / 60;
  END IF;
  
  -- Subtrair intervalo se definido
  IF p_break_start IS NOT NULL AND p_break_end IS NOT NULL THEN
    IF p_break_end > p_break_start THEN
      v_intervalo_minutos := EXTRACT(EPOCH FROM (p_break_end - p_break_start)) / 60;
    END IF;
  END IF;
  
  RETURN GREATEST(0, v_total_minutos - v_intervalo_minutos);
END;
$$;


ALTER FUNCTION public.calcular_carga_horaria_minutos(p_start_time time without time zone, p_end_time time without time zone, p_break_start time without time zone, p_break_end time without time zone) OWNER TO postgres;

--
-- Name: calculate_payroll_summary(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_payroll_summary(p_employee_id uuid, p_company_id text, p_start_date date, p_end_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_worked INTEGER;
    v_expected INTEGER;
    v_overtime INTEGER;
    v_absence INTEGER;
    v_night INTEGER;
    v_late INTEGER;
    v_work_days INTEGER;
    v_absence_days INTEGER;
BEGIN
    -- Calcular totais do per├¡odo
    SELECT 
        COALESCE(SUM(worked_minutes), 0),
        COALESCE(SUM(expected_minutes), 0),
        COALESCE(SUM(overtime_minutes), 0),
        COALESCE(SUM(absence_minutes), 0),
        COALESCE(SUM(night_minutes), 0),
        COALESCE(SUM(late_minutes), 0),
        COUNT(*) FILTER (WHERE worked_minutes > 0),
        COUNT(*) FILTER (WHERE is_absence = TRUE)
    INTO v_worked, v_expected, v_overtime, v_absence, v_night, v_late, v_work_days, v_absence_days
    FROM timesheets_daily
    WHERE employee_id = p_employee_id
    AND company_id = p_company_id
    AND date BETWEEN p_start_date AND p_end_date;
    
    -- Montar resultado
    v_result := jsonb_build_object(
        'employee_id', p_employee_id,
        'period_start', p_start_date,
        'period_end', p_end_date,
        'total_worked_minutes', v_worked,
        'total_expected_minutes', v_expected,
        'total_overtime_minutes', v_overtime,
        'total_absence_minutes', v_absence,
        'total_night_minutes', v_night,
        'total_late_minutes', v_late,
        'total_work_days', v_work_days,
        'total_absence_days', v_absence_days,
        'worked_hours', ROUND(v_worked / 60.0, 2),
        'expected_hours', ROUND(v_expected / 60.0, 2),
        'overtime_hours', ROUND(v_overtime / 60.0, 2),
        'absence_hours', ROUND(v_absence / 60.0, 2),
        'night_hours', ROUND(v_night / 60.0, 2),
        'late_hours', ROUND(v_late / 60.0, 2)
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.calculate_payroll_summary(p_employee_id uuid, p_company_id text, p_start_date date, p_end_date date) OWNER TO postgres;

