-- Name: FUNCTION calculate_payroll_summary(p_employee_id uuid, p_company_id text, p_start_date date, p_end_date date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.calculate_payroll_summary(p_employee_id uuid, p_company_id text, p_start_date date, p_end_date date) IS 'Calcula o resumo de jornada de um funcion├írio no per├¡odo';


--
-- Name: claim_device_user_sync_batch(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_device_user_sync_batch(p_device_id uuid, p_limit integer DEFAULT 100) RETURNS TABLE(sync_id uuid, user_id uuid, identifier text, identifier_type text, external_id_on_device text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH picked AS (
    SELECT d.id
    FROM public.device_user_sync d
    WHERE d.device_id = p_device_id
      AND d.sync_status IN ('pending', 'error')
      AND d.sync_attempts < 5
      AND (
        d.last_sync_at IS NULL
        OR d.last_sync_at <= NOW() - make_interval(secs => GREATEST(d.sync_attempts, 1) * 2)
      )
    ORDER BY d.created_at ASC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100)
    FOR UPDATE SKIP LOCKED
  ),
  touched AS (
    UPDATE public.device_user_sync d
      SET last_sync_at = NOW(),
          updated_at = NOW()
    FROM picked p
    WHERE d.id = p.id
    RETURNING d.id, d.user_id, d.identifier_value, d.identifier_type, d.external_id_on_device, d.created_at
  )
  SELECT t.id, t.user_id, t.identifier_value, t.identifier_type, t.external_id_on_device, t.created_at
  FROM touched t
  ORDER BY t.created_at ASC;
END;
$$;


ALTER FUNCTION public.claim_device_user_sync_batch(p_device_id uuid, p_limit integer) OWNER TO postgres;

