--

CREATE FUNCTION public.cleanup_old_logs_batch() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_limit integer := 1000;
BEGIN
  DELETE FROM public.rep_punch_logs
  WHERE id IN (
    SELECT id
    FROM public.rep_punch_logs
    WHERE created_at < NOW() - INTERVAL '30 days'
    ORDER BY created_at ASC
    LIMIT v_limit
  );

  DELETE FROM public.clock_event_logs
  WHERE id IN (
    SELECT id
    FROM public.clock_event_logs
    WHERE created_at < NOW() - INTERVAL '30 days'
    ORDER BY created_at ASC
    LIMIT v_limit
  );
END;
$$;


