--
-- Name: consume_hours(uuid, text, numeric, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_hours(p_employee_id uuid, p_company_id text, p_hours numeric, p_date date DEFAULT CURRENT_DATE, p_source text DEFAULT 'manual_debit'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev NUMERIC := 0;
  v_new NUMERIC := 0;
  v_take NUMERIC := 0;
BEGIN
  SELECT COALESCE(balance, 0) INTO v_prev
  FROM public.bank_hours
  WHERE employee_id = p_employee_id AND company_id = p_company_id
  ORDER BY date DESC, created_at DESC
  LIMIT 1;

  v_take := GREATEST(COALESCE(p_hours, 0), 0);
  v_new := GREATEST(COALESCE(v_prev, 0) - v_take, 0);

    employee_id, company_id, date, hours_added, hours_removed, balance, source, created_at
  ) VALUES (
    p_employee_id, p_company_id, COALESCE(p_date, CURRENT_DATE),
    0, v_take, v_new, p_source, NOW()
  );

  RETURN jsonb_build_object('success', true, 'previous_balance', v_prev, 'balance', v_new);
END;
$$;


ALTER FUNCTION public.consume_hours(p_employee_id uuid, p_company_id text, p_hours numeric, p_date date, p_source text) OWNER TO postgres;

--
-- Name: create_tenant_onboarding(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_tenant_onboarding(p_nome text, p_slug text, p_plan text DEFAULT 'free'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tid uuid;
  v_settings jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'N├úo autenticado';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = auth.uid()
      AND u.company_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Usu├írio j├í vinculado a um tenant';
  END IF;

  v_tid := gen_random_uuid();
  v_settings := jsonb_build_object(
    'fence', jsonb_build_object('lat', -23.5614, 'lng', -46.6559, 'radius', 150),
    'allowManualPunch', true,
    'requirePhoto', false,
    'standardHours', jsonb_build_object('start', '09:00', 'end', '18:00'),
    'delayPolicy', jsonb_build_object('toleranceMinutes', 15)
  );

    id, nome, name, slug, settings, plan, journey_settings, created_at, updated_at
  ) VALUES (
    v_tid,
    p_nome,
    p_nome,
    p_slug,
    v_settings,
    COALESCE(nullif(trim(p_plan), ''), 'free'),
    jsonb_build_object(
      'dailyMinutes', 480,
      'weeklyMinutes', 2400,
      'lateToleranceMinutes', 15,
      'timeBankEnabled', true,
      'overtimePolicy', 'clt_default',
      'mandatoryBreakMinutes', 60
    ),
    now(),
    now()
  );

  UPDATE public.users
  SET company_id = v_tid
  WHERE id = auth.uid();

  VALUES (v_tid, 'journey', '{}'::jsonb)
  ON CONFLICT (company_id, key) DO NOTHING;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'tenant_audit_log') THEN
    VALUES (v_tid, auth.uid(), 'tenant_onboarding', jsonb_build_object('slug', p_slug, 'plan', COALESCE(p_plan, 'free')));
  END IF;

  RETURN jsonb_build_object('tenant_id', v_tid, 'ok', true);
END;
$$;


