COMMENT ON FUNCTION public.create_tenant_onboarding(p_nome text, p_slug text, p_plan text) IS 'Cria empresa (tenant), v├¡nculo do usu├írio atual como admin e configura├º├Áes padr├úo de jornada.';


--
-- Name: delete_notification(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_notification(p_notification_id uuid, p_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_deleted_count INT;
BEGIN
  -- Verificar que o usu├írio est├í deletando sua pr├│pria notifica├º├úo
  IF (SELECT user_id FROM public.notifications WHERE id = p_notification_id) != p_user_id THEN
    RAISE EXCEPTION 'N├úo autorizado: notifica├º├úo n├úo pertence ao usu├írio'
      USING ERRCODE = '42501';
  END IF;

  -- Deletar a notifica├º├úo
  DELETE FROM public.notifications
  WHERE id = p_notification_id AND user_id = p_user_id;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', v_deleted_count > 0,
    'deleted_count', v_deleted_count
  );
END;
$$;


