--
-- Name: enforce_company_plan_employee_limit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_company_plan_employee_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max int;
  v_plan text;
  v_cnt int;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.role, '') <> 'employee' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.status, 'active') <> 'active' THEN
    RETURN NEW;
  END IF;
  IF NEW.company_id IS NULL OR btrim(NEW.company_id::text) = '' THEN
    RETURN NEW;
  END IF;

  SELECT lower(btrim(COALESCE(c.plan, 'free'))) INTO v_plan
  FROM public.companies c
  WHERE c.id = NEW.company_id;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF v_plan = 'enterprise' THEN
    RETURN NEW;
  END IF;
  IF v_plan = 'pro' THEN
    v_max := 50;
  ELSE
    v_max := 5;
  END IF;

  SELECT COUNT(*)::int INTO v_cnt
  FROM public.users u
  WHERE u.company_id = NEW.company_id
    AND u.role = 'employee'
    AND COALESCE(u.status, 'active') = 'active';

  IF v_cnt >= v_max THEN
    RAISE EXCEPTION 'PLAN_LIMIT_REACHED: Limite do plano atingido para colaboradores ativos'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_company_plan_employee_limit() OWNER TO postgres;

--
-- Name: FUNCTION enforce_company_plan_employee_limit(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.enforce_company_plan_employee_limit() IS 'Bloqueia INSERT de employee ativo quando o tenant j├í atingiu o m├íximo do plano (free=5, pro=50, enterprise=ilimitado).';


--
-- Name: enqueue_user_device_sync(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_user_device_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_device RECORD;
  v_identifier TEXT;
  v_identifier_type TEXT;
  v_cpf TEXT;
  v_pis TEXT;
  v_tenant_id UUID;
BEGIN
  -- N├úo bloquear cria├º├úo do usu├írio em caso de erro de sincroniza├º├úo.
  BEGIN
    v_tenant_id := NEW.company_id::uuid;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE LOG '[DEVICE_USER_SYNC][ERROR] tenant inv├ílido para user_id=% company_id=% detail=%',
        NEW.id, NEW.company_id, SQLERRM;
      RETURN NEW;
  END;

  IF COALESCE(NEW.role, '') NOT IN ('employee', 'admin', 'hr') THEN
    RETURN NEW;
  END IF;

  v_cpf := NULLIF(regexp_replace(COALESCE(NEW.cpf, ''), '\D', '', 'g'), '');
  v_pis := NULLIF(regexp_replace(COALESCE(NEW.pis_pasep, ''), '\D', '', 'g'), '');

  FOR v_device IN
    SELECT id, company_id, identifier_type
    FROM public.rep_devices
    WHERE company_id = NEW.company_id
      AND COALESCE(ativo, true) = true
      AND COALESCE(status, 'inativo') = 'ativo'
  LOOP
    v_identifier := NULL;
    v_identifier_type := COALESCE(v_device.identifier_type, 'pis');

    IF v_identifier_type = 'cpf' THEN
      v_identifier := v_cpf;
    ELSIF v_identifier_type = 'pis' THEN
      v_identifier := v_pis;
    ELSE
      v_identifier := COALESCE(v_cpf, v_pis);
    END IF;

    IF v_identifier IS NULL THEN
      RAISE LOG '[DEVICE_USER_SYNC][ERROR] identificador ausente device_id=% user_id=% mode=% cpf_present=% pis_present=%',
        v_device.id, NEW.id, v_identifier_type, (v_cpf IS NOT NULL), (v_pis IS NOT NULL);
      VALUES (
        v_device.id,
        'DEVICE_USER_SYNC_ENQUEUE',
        'erro',
        'Colaborador sem identificador v├ílido para sincroniza├º├úo',
        jsonb_build_object(
          'user_id', NEW.id,
          'company_id', NEW.company_id,
          'identifier_type', v_identifier_type,
          'cpf_present', (v_cpf IS NOT NULL),
          'pis_present', (v_pis IS NOT NULL)
        )
      );
      CONTINUE;
    END IF;

      tenant_id,
      device_id,
      user_id,
      identifier_type,
      identifier_value,
      sync_status,
      sync_attempts,
      sync_error,
      last_sync_at,
      created_at,
      updated_at
    )
    VALUES (
      v_tenant_id,
      v_device.id,
      NEW.id,
      v_identifier_type,
      v_identifier,
      'pending',
      0,
      NULL,
      NULL,
      NOW(),
      NOW()
    )
    ON CONFLICT (device_id, user_id) DO UPDATE
      SET identifier_type = EXCLUDED.identifier_type,
          identifier_value = EXCLUDED.identifier_value,
          sync_status = 'pending',
          sync_attempts = 0,
          sync_error = NULL,
          updated_at = NOW();
  END LOOP;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE LOG '[DEVICE_USER_SYNC][ERROR] falha inesperada user_id=% detail=%', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.enqueue_user_device_sync() OWNER TO postgres;

--
-- Name: ess_day_shift_times(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ess_day_shift_times(p_employee_id uuid, p_company_id text, p_js_dow integer) RETURNS TABLE(shift_start time without time zone, shift_end time without time zone, brk_start time without time zone, brk_end time without time zone, tol integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(ess.start_time::time, ws.start_time::time) AS shift_start,
    COALESCE(ess.end_time::time, ws.end_time::time) AS shift_end,
    COALESCE(ess.break_start::time, ws.break_start_time::time) AS brk_start,
    COALESCE(ess.break_end::time, ws.break_end_time::time) AS brk_end,
    COALESCE(
      ess.tolerance_minutes,
      ws.tolerance_minutes,
      ws.tolerancia_entrada,
      0
    )::INT AS tol
  FROM public.employee_shift_schedule ess
  LEFT JOIN public.work_shifts ws ON ws.id = COALESCE(ess.shift_id, ess.work_shift_id)
  WHERE ess.employee_id = p_employee_id
    AND ess.company_id::TEXT = p_company_id::TEXT
    AND ess.day_of_week = p_js_dow
    AND COALESCE(ess.is_workday, NOT COALESCE(ess.is_day_off, FALSE), TRUE) = TRUE
    AND (
      (ess.start_time IS NOT NULL AND ess.end_time IS NOT NULL)
      OR COALESCE(ess.shift_id, ess.work_shift_id) IS NOT NULL
    )
  LIMIT 1;
$$;


ALTER FUNCTION public.ess_day_shift_times(p_employee_id uuid, p_company_id text, p_js_dow integer) OWNER TO postgres;

--
-- Name: FUNCTION ess_day_shift_times(p_employee_id uuid, p_company_id text, p_js_dow integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ess_day_shift_times(p_employee_id uuid, p_company_id text, p_js_dow integer) IS 'Retorna hor├írios do dia na ESS (inline ou via turno). p_js_dow = EXTRACT(DOW) / getDay().';


--
-- Name: expire_hours(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_hours(p_company_id text, p_before date) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_count INT := 0;
BEGIN
  FOR r IN
    SELECT DISTINCT employee_id
    FROM public.bank_hours
    WHERE company_id = p_company_id
      AND date < p_before
  LOOP
    PERFORM public.consume_hours(
      r.employee_id,
      p_company_id,
      COALESCE((
        SELECT SUM(GREATEST(hours_added, 0) - GREATEST(hours_removed, 0))
        FROM public.bank_hours
        WHERE company_id = p_company_id
          AND employee_id = r.employee_id
          AND date < p_before
      ), 0),
      p_before,
      'expiration'
    );
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'employees_processed', v_count, 'before', p_before);
END;
$$;


ALTER FUNCTION public.expire_hours(p_company_id text, p_before date) OWNER TO postgres;

--
-- Name: fix_and_promote_pending_rep_punches(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fix_and_promote_pending_rep_punches(p_company_id uuid, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  r record;
  v_cid text;
  v_lim int;
  v_processed int := 0;
  v_fixed int := 0;
  v_promoted int := 0;
  v_unresolved int := 0;
  v_m jsonb;
  v_user_id text;
  v_strategy text;
  v_record_id text;
  v_existing_record_id text;
  v_user_uuid uuid;
  v_d11 text;
  v_promote_line text;
  v_promote_blob text;
  v_promote_blob_d text;
  v_mt_total int := 0;
  v_mt_strong int := 0;
  v_mt_weak int := 0;
  v_mt_direct int := 0;
  v_mt_unres int := 0;
  v_mt_ambig int := 0;
  v_row_ambig boolean;
BEGIN
  v_cid := btrim(p_company_id::text);
  v_lim := GREATEST(1, LEAST(COALESCE(p_limit, 200), 5000));

  FOR r IN
    SELECT id, nsr, pis, cpf, matricula, data_hora, tipo_marcacao, raw_data, resolved_user_id
    FROM public.rep_punch_logs
    WHERE btrim(company_id::text) = v_cid
      AND time_record_id IS NULL
      AND COALESCE(ignored, false) = false
      AND (resolved_user_id IS NULL OR btrim(COALESCE(resolved_user_id, '')) = '')
    ORDER BY data_hora ASC
    LIMIT v_lim
  LOOP
    v_processed := v_processed + 1;
    v_mt_total := v_mt_total + 1;
    v_row_ambig := false;

    v_m := public.rep_match_user_id_for_rep_punch_row(
      v_cid,
      r.pis,
      r.cpf,
      r.matricula,
      COALESCE(r.raw_data, '{}'::jsonb)
    );

    v_user_id := NULLIF(btrim(COALESCE(v_m->>'user_id', '')), '');
    v_strategy := NULLIF(btrim(COALESCE(v_m->>'match_strategy', '')), '');

    IF v_user_id IS NULL THEN
      v_user_uuid := NULL;
      v_promote_line := NULL;
      v_promote_blob_d := NULL;
      IF r.raw_data IS NOT NULL AND jsonb_typeof(r.raw_data) = 'object' THEN
        v_promote_line := public.rep_compact_afd_line_from_punch_raw(r.raw_data);
      END IF;
      IF v_promote_line IS NOT NULL THEN
        v_promote_blob := public.rep_afd_identifier_blob_from_compact_line(
          regexp_replace(v_promote_line, '\s', '', 'g')
        );
        IF v_promote_blob IS NOT NULL THEN
          v_promote_blob_d := regexp_replace(v_promote_blob, '\D', '', 'g');
        END IF;
      END IF;

      SELECT f.user_id, f.saw_ambiguous
      INTO v_user_uuid, v_row_ambig
      FROM public.rep_match_user_direct_11_first_unique_from_candidates(
        v_cid,
        ARRAY[
          COALESCE(public.rep_afd_canonical_11_digits(r.pis), ''),
          COALESCE(public.rep_afd_canonical_11_digits(r.cpf), ''),
          COALESCE(NULLIF(trim(r.pis), ''), ''),
          COALESCE(NULLIF(trim(r.cpf), ''), ''),
          COALESCE(v_promote_blob_d, ''),
          CASE WHEN v_promote_blob_d IS NOT NULL AND length(v_promote_blob_d) >= 11 THEN substring(v_promote_blob_d from 1 for 11) END,
          CASE WHEN v_promote_blob_d IS NOT NULL AND length(v_promote_blob_d) > 11 THEN substring(v_promote_blob_d from length(v_promote_blob_d) - 10 for 11) END
        ]
      ) f;

      IF v_user_uuid IS NOT NULL THEN
        v_user_id := v_user_uuid::text;
        v_strategy := 'direct_11_no_dv';
        RAISE LOG '[REP INGEST FORCE MATCH] %', jsonb_build_object('nsr', r.nsr, 'resolved_user_id', v_user_id);
      END IF;
    END IF;

    IF v_user_id IS NULL THEN
      v_unresolved := v_unresolved + 1;
      v_mt_unres := v_mt_unres + 1;
      IF v_row_ambig THEN
        v_mt_ambig := v_mt_ambig + 1;
      END IF;
      RAISE LOG '[REP STILL UNRESOLVED] %', jsonb_build_object('nsr', r.nsr, 'reason', 'no_match');
      CONTINUE;
    END IF;

    IF v_strategy = 'weak_pis_match' THEN
      v_mt_weak := v_mt_weak + 1;
    ELSIF v_strategy = 'direct_11_no_dv' THEN
      v_mt_direct := v_mt_direct + 1;
    ELSE
      v_mt_strong := v_mt_strong + 1;
    END IF;

    UPDATE public.rep_punch_logs
    SET
      resolved_user_id = v_user_id,
      raw_data = (
        COALESCE(raw_data, '{}'::jsonb)
        - 'unresolved'
        - 'unresolved_reason'
      )
      || jsonb_build_object('canonical_user_id', v_user_id)
      || CASE
        WHEN v_strategy = 'direct_11_no_dv' THEN jsonb_build_object(
          'match_strategy', 'direct_11_no_dv',
          'matched_user_id', v_user_id,
          'confidence', 'low',
          'promote_force_match', true
        )
        ELSE COALESCE(v_m->'raw_data_patch', '{}'::jsonb)
      END
    WHERE id = r.id
      AND (resolved_user_id IS NULL OR btrim(COALESCE(resolved_user_id, '')) = '');

    v_fixed := v_fixed + 1;
    RAISE LOG '[REP REPROCESS] %', jsonb_build_object('nsr', r.nsr, 'before', NULL, 'after', v_user_id, 'strategy', v_strategy);

    v_existing_record_id := NULL;
    IF r.nsr IS NOT NULL THEN
      SELECT tr.id::text INTO v_existing_record_id
      FROM public.time_records tr
      WHERE tr.company_id = v_cid
        AND tr.nsr = r.nsr
        AND tr.source = 'rep'
      LIMIT 1;
    END IF;

    IF v_existing_record_id IS NOT NULL THEN
      UPDATE public.rep_punch_logs
      SET
        time_record_id = v_existing_record_id,
        status = 'promoted'
      WHERE id = r.id
        AND time_record_id IS NULL;
      v_promoted := v_promoted + 1;
      RAISE LOG '[REP PROMOTE SUCCESS] %', jsonb_build_object('nsr', r.nsr, 'user_id', v_user_id);
      CONTINUE;
    END IF;

    v_record_id := gen_random_uuid()::text;
      id, user_id, company_id, type, method, timestamp, source, nsr, fraud_score, is_late
    ) VALUES (
      v_record_id,
      v_user_id,
      v_cid,
      CASE UPPER(LEFT(COALESCE(r.tipo_marcacao, 'E'), 1))
        WHEN 'E' THEN 'entrada'
        WHEN 'S' THEN 'sa├¡da'
        WHEN 'P' THEN 'pausa'
        ELSE 'entrada'
      END,
      'rep',
      r.data_hora,
      'rep',
      r.nsr,
      0,
      FALSE
    );

    UPDATE public.rep_punch_logs
    SET
      time_record_id = v_record_id,
      status = 'promoted'
    WHERE id = r.id
      AND time_record_id IS NULL;

    v_promoted := v_promoted + 1;
    RAISE LOG '[REP PROMOTE SUCCESS] %', jsonb_build_object('nsr', r.nsr, 'user_id', v_user_id);
  END LOOP;

  IF v_mt_total > 0 THEN
    PERFORM public.rep_emit_rep_match_metrics(
      'fix_and_promote',
      v_cid,
      v_mt_total,
      v_mt_strong,
      v_mt_weak,
      v_mt_direct,
      v_mt_unres,
      v_mt_ambig
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'processed', v_processed,
    'fixed', v_fixed,
    'promoted', v_promoted,
    'still_unresolved', v_unresolved,
    'batch_limit', v_lim
  );
END;
$$;


ALTER FUNCTION public.fix_and_promote_pending_rep_punches(p_company_id uuid, p_limit integer) OWNER TO postgres;

