-- Name: FUNCTION fix_and_promote_pending_rep_punches(p_company_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fix_and_promote_pending_rep_punches(p_company_id uuid, p_limit integer) IS 'Lote: RPC + direct_11; [REP MATCH METRICS] por lote.';


--
-- Name: get_colaborador_jornada_ativa(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_colaborador_jornada_ativa(p_colaborador_id uuid, p_data date DEFAULT CURRENT_DATE) RETURNS TABLE(jornada_id uuid, horario_id uuid, escala_id uuid, horario_nome text, escala_nome text, data_inicio date, data_fim date)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    cj.id AS jornada_id,
    cj.horario_id,
    cj.escala_id,
    ws.name AS horario_nome,
    s.name AS escala_nome,
    cj.data_inicio,
    cj.data_fim
  FROM public.colaborador_jornada cj
  LEFT JOIN public.work_shifts ws ON ws.id = cj.horario_id
  LEFT JOIN public.schedules s ON s.id = cj.escala_id
  WHERE cj.colaborador_id = p_colaborador_id
    AND cj.ativo = true
    AND cj.data_inicio <= p_data
    AND (cj.data_fim IS NULL OR cj.data_fim >= p_data)
  ORDER BY cj.data_inicio DESC
  LIMIT 1;
END;
$$;


