--
-- Name: insert_punch_evidence_for_own_punch(text, text, numeric, numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_punch_evidence_for_own_punch(p_time_record_id text, p_photo_url text DEFAULT NULL::text, p_location_lat numeric DEFAULT NULL::numeric, p_location_lng numeric DEFAULT NULL::numeric, p_device_id text DEFAULT NULL::text, p_fraud_score numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_id text;
BEGIN
  SET LOCAL row_security TO off;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sess├úo inv├ílida ou expirada. Fa├ºa login novamente.'
      USING ERRCODE = '42501';
  END IF;

  v_id := trim(both from p_time_record_id);
  IF v_id IS NULL OR v_id = '' THEN
    RAISE EXCEPTION 'time_record_id obrigat├│rio';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.time_records tr
    WHERE tr.id::text = v_id
      AND tr.user_id IS NOT DISTINCT FROM auth.uid()::text
  ) THEN
    RAISE EXCEPTION 'Marca├º├úo n├úo encontrada ou n├úo pertence ao usu├írio.'
      USING ERRCODE = '42501';
  END IF;

    time_record_id,
    photo_url,
    location_lat,
    location_lng,
    device_id,
    fraud_score
  ) VALUES (
    v_id::uuid,
    p_photo_url,
    p_location_lat,
    p_location_lng,
    p_device_id,
    p_fraud_score
  );
END;
$$;


