-- Name: FUNCTION insert_punch_evidence_for_own_punch(p_time_record_id text, p_photo_url text, p_location_lat numeric, p_location_lng numeric, p_device_id text, p_fraud_score numeric); Type: COMMENT; Schema: public; Owner: postgres
--

