--
-- Name: is_company_holiday(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_company_holiday(p_company_id text, p_date date) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_is_holiday boolean;
BEGIN
  v_is_holiday := EXISTS (
    SELECT 1 FROM public.holidays
    WHERE company_id = p_company_id
      AND date = p_date
  );
  
  RETURN COALESCE(v_is_holiday, false);
END;
$$;


ALTER FUNCTION public.is_company_holiday(p_company_id text, p_date date) OWNER TO postgres;

--
-- Name: is_employee_day_off(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_employee_day_off(p_employee_id uuid, p_date date) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_dow smallint;
  v_off boolean;
BEGIN
  v_dow := DATE_PART('dow', p_date)::smallint;

  v_off := (
    SELECT COALESCE(ess.is_day_off, NOT COALESCE(ess.is_workday, TRUE), FALSE)
    FROM public.employee_shift_schedule ess
    WHERE ess.employee_id = p_employee_id
      AND ess.day_of_week = v_dow
    LIMIT 1
  );

  RETURN COALESCE(v_off, FALSE);
END;
$$;


ALTER FUNCTION public.is_employee_day_off(p_employee_id uuid, p_date date) OWNER TO postgres;

--
-- Name: is_night_shift_schedule(time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_night_shift_schedule(p_entrada time without time zone, p_saida_final time without time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (EXTRACT(HOUR FROM p_entrada)::int * 60 + EXTRACT(MINUTE FROM p_entrada)::int)
       > (EXTRACT(HOUR FROM p_saida_final)::int * 60 + EXTRACT(MINUTE FROM p_saida_final)::int);
$$;


ALTER FUNCTION public.is_night_shift_schedule(p_entrada time without time zone, p_saida_final time without time zone) OWNER TO postgres;

--
-- Name: lgpd_archive_rep_punch_logs(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lgpd_archive_rep_punch_logs(p_company_id uuid, p_years integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_cutoff TIMESTAMPTZ;
  v_count INT;
BEGIN
  v_cutoff := NOW() - make_interval(years => GREATEST(p_years, 1));
  UPDATE public.rep_punch_logs
  SET archived_at = COALESCE(archived_at, NOW())
  WHERE company_id = p_company_id::text
    AND created_at < v_cutoff
    AND archived_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'archived_count', v_count, 'cutoff', v_cutoff);
END;
$$;


ALTER FUNCTION public.lgpd_archive_rep_punch_logs(p_company_id uuid, p_years integer) OWNER TO postgres;

--
-- Name: lgpd_export_user_data(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lgpd_export_user_data(p_user_id uuid, p_requester_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_user public.users%ROWTYPE;
  v_punches jsonb;
  v_audit jsonb;
BEGIN
  SELECT * INTO v_user FROM public.users WHERE id = p_user_id LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'USER_NOT_FOUND');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC), '[]'::jsonb)
  INTO v_punches
  FROM (
    SELECT id, data_hora, tipo_marcacao, nsr, origem, source, created_at, archived_at, anonymized_at
    FROM public.rep_punch_logs
    WHERE company_id = v_user.company_id::text
      AND (resolved_user_id = p_user_id::text OR pis = v_user.pis_pasep OR cpf = v_user.cpf)
    LIMIT 50000
  ) r;

  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.created_at DESC), '[]'::jsonb)
  INTO v_audit
  FROM (
    SELECT action, entity, entity_id, severity, metadata, created_at
    FROM public.audit_logs
    WHERE user_id = p_user_id::text OR entity_id = p_user_id
    ORDER BY created_at DESC
    LIMIT 5000
  ) a;

    id, user_id, company_id, action, entity, entity_id, severity, details, metadata, created_at, "timestamp"
  ) VALUES (
    gen_random_uuid(),
    COALESCE(p_requester_id::text, NULL),
    v_user.company_id::text,
    'LGPD_EXPORT_USER_DATA',
    'users',
    p_user_id,
    'SECURITY',
    jsonb_build_object('exported_user_id', p_user_id),
    jsonb_build_object('exported_user_id', p_user_id),
    NOW(),
    NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'exported_at', NOW(),
    'profile', jsonb_build_object(
      'id', v_user.id,
      'company_id', v_user.company_id,
      'nome', v_user.nome,
      'email', v_user.email,
      'cpf', v_user.cpf,
      'pis_pasep', v_user.pis_pasep,
      'numero_identificador', v_user.numero_identificador,
      'numero_folha', v_user.numero_folha,
      'role', v_user.role,
      'status', v_user.status,
      'admissao', v_user.admissao,
      'demissao', v_user.demissao,
      'data_classification', v_user.data_classification
    ),
    'rep_punch_logs', v_punches,
    'audit_logs', v_audit
  );
END;
$$;


