--
-- Name: log_audit_event(uuid, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_audit_event(p_user_id uuid, p_company_id text, p_action text, p_entity text, p_entity_id text, p_metadata jsonb DEFAULT '{}'::jsonb, p_severity text DEFAULT 'info'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_id UUID;
  v_hash TEXT;
BEGIN
  v_hash := encode(
    digest(
      p_user_id::text || '|' || p_action || '|' || p_entity || '|' || p_entity_id || '|' || extract(epoch from now())::text,
      'sha256'
    ),
    'hex'
  );

    user_id, company_id, action, entity, entity_id,
    timestamp, metadata, severity, integrity_hash
  ) VALUES (
    p_user_id, p_company_id, p_action, p_entity, p_entity_id,
    NOW(), p_metadata, p_severity, v_hash
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


