--
-- Name: mark_notification_read(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_notification_read(p_notification_id uuid, p_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_updated_count INT;
BEGIN
  -- Verificar que o usu├írio est├í atualizando sua pr├│pria notifica├º├úo
  IF (SELECT user_id FROM public.notifications WHERE id = p_notification_id) != p_user_id THEN
    RAISE EXCEPTION 'N├úo autorizado: notifica├º├úo n├úo pertence ao usu├írio'
      USING ERRCODE = '42501';
  END IF;

  -- Marcar como lida
  UPDATE public.notifications
  SET read = true
  WHERE id = p_notification_id AND user_id = p_user_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', v_updated_count > 0,
    'updated_count', v_updated_count
  );
END;
$$;


ALTER FUNCTION public.mark_notification_read(p_notification_id uuid, p_user_id text) OWNER TO postgres;

