-- Name: FUNCTION mark_notification_read(p_notification_id uuid, p_user_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.mark_notification_read(p_notification_id uuid, p_user_id text) IS 'Mark a notification as read with RLS bypass. Verifies ownership before update.';


--
-- Name: night_journey_post_midnight_cutoff_minutes(time without time zone, time without time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.night_journey_post_midnight_cutoff_minutes(p_entrada time without time zone, p_saida_final time without time zone, p_tolerance_min integer DEFAULT 60) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT GREATEST(
    (EXTRACT(HOUR FROM p_saida_final)::int * 60 + EXTRACT(MINUTE FROM p_saida_final)::int) + COALESCE(p_tolerance_min, 60),
    (
      (EXTRACT(HOUR FROM p_entrada)::int * 60 + EXTRACT(MINUTE FROM p_entrada)::int) + 720
    ) % 1440
  );
$$;


ALTER FUNCTION public.night_journey_post_midnight_cutoff_minutes(p_entrada time without time zone, p_saida_final time without time zone, p_tolerance_min integer) OWNER TO postgres;

--
-- Name: FUNCTION night_journey_post_midnight_cutoff_minutes(p_entrada time without time zone, p_saida_final time without time zone, p_tolerance_min integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.night_journey_post_midnight_cutoff_minutes(p_entrada time without time zone, p_saida_final time without time zone, p_tolerance_min integer) IS 'Minutos ap├│s meia-noite (dia civil) at├® os quais batidas pertencem ├á jornada noturna iniciada no dia anterior.';


--
-- Name: normalize_time_record_punch_type(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalize_time_record_punch_type(p_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE lower(trim(COALESCE(p_type, '')))
    WHEN 'sa├¡da' THEN 'saida'
    WHEN 'saida' THEN 'saida'
    WHEN 'entrada' THEN 'entrada'
    WHEN 'pausa' THEN 'pausa'
    WHEN 'intervalo_saida' THEN 'pausa'
    WHEN 'intervalo_volta' THEN 'entrada'
    WHEN 'e' THEN 'entrada'
    WHEN 's' THEN 'saida'
    WHEN 'p' THEN 'pausa'
    WHEN 'b' THEN 'entrada'
    ELSE lower(trim(COALESCE(p_type, '')))
  END;
$$;


ALTER FUNCTION public.normalize_time_record_punch_type(p_type text) OWNER TO postgres;

