--
-- Name: punches_block_closed_timesheet(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.punches_block_closed_timesheet() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_employee_id text;
  v_company_id text;
  v_ref_ts timestamptz;
  v_closed boolean;
  v_bypass text;
BEGIN
  v_bypass := COALESCE(current_setting('ponto.allow_closed_timesheet_write', true), '');
  IF v_bypass = '1' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    v_employee_id := NEW.employee_id::text;
    v_company_id := NEW.company_id::text;
    v_ref_ts := COALESCE(NEW.created_at, NOW());
  ELSE
    v_employee_id := OLD.employee_id::text;
    v_company_id := OLD.company_id::text;
    v_ref_ts := COALESCE(OLD.created_at, NOW());
  END IF;
  SELECT public.timesheet_is_closed_for_stamp(v_company_id, v_employee_id, v_ref_ts) INTO v_closed;
  IF v_closed THEN
    RAISE EXCEPTION 'PERIODO_FECHADO' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.punches_block_closed_timesheet() OWNER TO postgres;

--
-- Name: punches_normalize_type(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.punches_normalize_type(p_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE lower(btrim(COALESCE(p_type, '')))
    WHEN 'e' THEN 'entrada'
    WHEN 'in' THEN 'entrada'
    WHEN 'clock_in' THEN 'entrada'
    WHEN 'entrada' THEN 'entrada'
    WHEN 's' THEN 'saida'
    WHEN 'out' THEN 'saida'
    WHEN 'clock_out' THEN 'saida'
    WHEN 'sa├¡da' THEN 'saida'
    WHEN 'saida' THEN 'saida'
    WHEN 'p' THEN 'pausa'
    WHEN 'pausa' THEN 'pausa'
    WHEN 'break_start' THEN 'intervalo_saida'
    WHEN 'intervalo_saida' THEN 'intervalo_saida'
    WHEN 'break_end' THEN 'intervalo_volta'
    WHEN 'intervalo_volta' THEN 'intervalo_volta'
    ELSE 'entrada'
  END;
$$;


ALTER FUNCTION public.punches_normalize_type(p_type text) OWNER TO postgres;

