--
-- Name: pwd_bootstrap_company_defaults(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pwd_bootstrap_company_defaults(p_company_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_id text := btrim(COALESCE(p_company_id, ''));
  v_shift_id uuid;
BEGIN
  IF v_company_id = '' THEN
    RETURN;
  END IF;

    company_id, gps_required, photo_required, allow_manual_punch,
    late_tolerance_minutes, min_break_minutes, timezone, language,
    email_alerts, daily_email_summary, punch_reminder, password_min_length,
    require_numbers, require_special_chars, session_timeout_minutes,
    default_entry_time, default_exit_time, allow_time_bank
  )
  VALUES (
    v_company_id::uuid, false, false, true,
    10, 60, 'America/Sao_Paulo', 'pt-BR',
    true, false, true, 8,
    false, false, 60,
    '08:00'::time, '18:00'::time, true
  )
  ON CONFLICT DO NOTHING;

  VALUES (v_company_id::uuid, 'MATRIZ', 'Matriz')
  ON CONFLICT (company_id, codigo) DO NOTHING;

  SELECT gen_random_uuid(), v_company_id::uuid, 'Administrativo'
  WHERE NOT EXISTS (
    SELECT 1
      FROM public.departments
     WHERE company_id::text = v_company_id
       AND lower(btrim(name)) = 'administrativo'
  );

    company_id, work_on_saturday, saturday_overtime_type,
    time_bank_enabled, tolerance_minutes, night_additional_percent, dsr_enabled
  )
  VALUES (v_company_id::uuid, false, '100', true, 10, 20, true)
  ON CONFLICT (company_id) DO NOTHING;

  SELECT id INTO v_shift_id
    FROM public.work_shifts
   WHERE company_id::text = v_company_id
     AND name IN ('Jornada 44h Semanais', 'Segunda a Sexta')
   LIMIT 1;

  IF v_shift_id IS NULL THEN
    VALUES (v_company_id::uuid, 'Jornada 44h Semanais', '08:00'::time, '18:00'::time, '12:00'::time, '13:00'::time, 10, true)
    RETURNING id INTO v_shift_id;
  END IF;

  SELECT v_company_id::uuid, 'Segunda a Sexta', ARRAY[1,2,3,4,5]::integer[], v_shift_id
  WHERE NOT EXISTS (
    SELECT 1
      FROM public.schedules
     WHERE company_id::text = v_company_id
       AND lower(btrim(name)) = 'segunda a sexta'
  );
END;
$$;


