--
-- Name: reclassify_operational_journey_types(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reclassify_operational_journey_types(p_company_id uuid, p_user_id uuid, p_operational_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_pos int := 0;
  v_updated int := 0;
  v_new_type text;
BEGIN
  PERFORM set_config('ponto.operational_journey_reclassify', '1', true);
  PERFORM set_config('ponto.skip_time_record_sequence_check', '1', true);

  FOR r IN
    SELECT tr.id, tr.type AS old_type
    FROM public.time_records tr
    WHERE tr.company_id = p_company_id
      AND tr.user_id = p_user_id
      AND public.time_record_operational_date_sp(p_user_id, p_company_id, COALESCE(tr.timestamp, tr.created_at)) = p_operational_date
      AND (COALESCE(tr.source, '') = 'rep' OR COALESCE(tr.method, '') ILIKE '%rep%')
    ORDER BY COALESCE(tr.timestamp, tr.created_at), tr.id
  LOOP
    v_new_type := public.rep_journey_type_for_position(v_pos);
    IF r.old_type IS DISTINCT FROM v_new_type THEN
      UPDATE public.time_records
      SET
        type = v_new_type,
        raw_data = COALESCE(raw_data, '{}'::jsonb) || jsonb_build_object(
          'journey_type_reclassified', true,
          'journey_operational_date', p_operational_date::text,
          'journey_type_position', v_pos,
          'journey_type_before', r.old_type
        )
      WHERE id = r.id;
      v_updated := v_updated + 1;
    END IF;
    v_pos := v_pos + 1;
  END LOOP;

  PERFORM set_config('ponto.skip_time_record_sequence_check', '0', true);
  PERFORM set_config('ponto.operational_journey_reclassify', '0', true);

  RETURN jsonb_build_object('updated', v_updated, 'operational_date', p_operational_date);
EXCEPTION
  WHEN OTHERS THEN
    PERFORM set_config('ponto.skip_time_record_sequence_check', '0', true);
    PERFORM set_config('ponto.operational_journey_reclassify', '0', true);
    RAISE;
END;
$$;


ALTER FUNCTION public.reclassify_operational_journey_types(p_company_id uuid, p_user_id uuid, p_operational_date date) OWNER TO postgres;

--
-- Name: reclassify_punches_by_schedule(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reclassify_punches_by_schedule(p_company_id uuid, p_employee_id uuid DEFAULT NULL::uuid, p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_record RECORD;
  v_interpretation JSONB;
  v_updated INT := 0;
  v_types TEXT[] := ARRAY[]::TEXT[];
BEGIN
  -- Buscar batidas do dia ordenadas por timestamp
  FOR v_record IN
    SELECT 
      tr.id,
      tr.user_id,
      tr.timestamp,
      tr.type
    FROM public.time_records tr
    WHERE tr.company_id = p_company_id
      AND (p_employee_id IS NULL OR tr.user_id = p_employee_id::text)
      AND DATE(tr.timestamp AT TIME ZONE 'America/Sao_Paulo') = p_date
      AND tr.source = 'rep'
      AND tr.method = 'rep'
    ORDER BY tr.timestamp ASC
  LOOP
    -- Interpretar esta batida baseado nas anteriores
    v_interpretation := public.interpret_punch_by_schedule(
      v_record.user_id::UUID,
      p_company_id,
      v_record.timestamp,
      v_types
    );
    
    -- Atualizar o tipo da batida
    UPDATE public.time_records
    SET type = v_interpretation->>'type',
        is_late = COALESCE((v_interpretation->>'is_late')::boolean, FALSE),
        updated_at = NOW()
    WHERE id = v_record.id;
    
    v_updated := v_updated + 1;
    v_types := array_append(v_types, v_interpretation->>'type');
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'updated', v_updated,
    'date', p_date,
    'employee_id', p_employee_id,
    'company_id', p_company_id
  );
END;
$$;


ALTER FUNCTION public.reclassify_punches_by_schedule(p_company_id uuid, p_employee_id uuid, p_date date) OWNER TO postgres;

--
-- Name: FUNCTION reclassify_punches_by_schedule(p_company_id uuid, p_employee_id uuid, p_date date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reclassify_punches_by_schedule(p_company_id uuid, p_employee_id uuid, p_date date) IS 'Reclassifica todas as batidas de um funcion├írio (ou todos) em uma data espec├¡fica baseado na escala.';


--
-- Name: record_login_attempt(text, inet, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_login_attempt(p_identifier text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text, p_successful boolean DEFAULT false) RETURNS TABLE(allowed boolean, remaining_attempts integer, locked_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_max_attempts INTEGER := 5;
  v_lockout_minutes INTEGER := 5;
  v_record public.login_attempts%ROWTYPE;
BEGIN
  -- Limpa tentativas antigas (> 24h)
  DELETE FROM public.login_attempts
  WHERE first_attempt_at < NOW() - INTERVAL '24 hours';

  -- Busca tentativas existentes
  SELECT * INTO v_record
  FROM public.login_attempts
  WHERE identifier = p_identifier
  ORDER BY last_attempt_at DESC
  LIMIT 1;

  -- Se bem sucedido, limpa tentativas
  IF p_successful THEN
    DELETE FROM public.login_attempts WHERE identifier = p_identifier;
    RETURN QUERY SELECT true, v_max_attempts, NULL::TIMESTAMPTZ;
    RETURN;
  END IF;

  -- Se est├í bloqueado
  IF v_record.locked_until IS NOT NULL AND v_record.locked_until > NOW() THEN
    RETURN QUERY SELECT false, 0, v_record.locked_until;
    RETURN;
  END IF;

  -- Incrementa ou cria nova tentativa
  IF v_record.id IS NULL THEN
      identifier, attempt_count, ip_address, user_agent
    ) VALUES (
      p_identifier, 1, p_ip_address, p_user_agent
    )
    RETURNING * INTO v_record;
  ELSE
    UPDATE public.login_attempts
    SET attempt_count = attempt_count + 1,
        last_attempt_at = NOW(),
        locked_until = CASE
          WHEN attempt_count + 1 >= v_max_attempts THEN NOW() + (v_lockout_minutes || ' minutes')::INTERVAL
          ELSE locked_until
        END
    WHERE id = v_record.id
    RETURNING * INTO v_record;
  END IF;

  RETURN QUERY SELECT
    (v_record.locked_until IS NULL OR v_record.locked_until <= NOW()),
    GREATEST(0, v_max_attempts - v_record.attempt_count),
    v_record.locked_until;
END;
$$;


ALTER FUNCTION public.record_login_attempt(p_identifier text, p_ip_address inet, p_user_agent text, p_successful boolean) OWNER TO postgres;

--
-- Name: refresh_current_operational_state(text, text, text, timestamp with time zone, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_current_operational_state(p_company_id text, p_employee_id text, p_source text DEFAULT 'time_record_insert'::text, p_event_at timestamp with time zone DEFAULT now(), p_force boolean DEFAULT false, p_correlation_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_company_txt text := btrim(COALESCE(p_company_id, ''));
  v_employee_txt text := btrim(COALESCE(p_employee_id, ''));
  v_company_uuid uuid;
  v_employee_uuid uuid;
  v_effective_event_at timestamptz;
  v_last public.time_records%ROWTYPE;
  v_status text := 'NO_SHIFT';
BEGIN
  IF v_company_txt = '' OR v_employee_txt = '' THEN
    RETURN;
  END IF;

  BEGIN
    v_company_uuid := v_company_txt::uuid;
    v_employee_uuid := v_employee_txt::uuid;
  EXCEPTION WHEN OTHERS THEN
    RETURN;
  END;

  SELECT tr.*
    INTO v_last
  FROM public.time_records tr
  WHERE tr.company_id::text = v_company_txt
    AND tr.user_id::text = v_employee_txt
  ORDER BY COALESCE(tr.timestamp, tr.created_at) DESC NULLS LAST
  LIMIT 1;

  IF FOUND THEN
    v_status := public._operational_status_from_punch_type(v_last.type);
  END IF;

  SELECT MAX(tr.timestamp)
    INTO v_effective_event_at
  FROM public.time_records tr
  WHERE tr.company_id::text = v_company_txt
    AND tr.user_id::text = v_employee_txt;

  v_effective_event_at := COALESCE(v_effective_event_at, p_event_at, now());

    company_id,
    employee_id,
    operational_status,
    last_punch_type,
    last_punch_record_id,
    last_punch_at,
    updated_at,
    last_update_source,
    state_version,
    last_event_sequence,
    state_source,
    last_event_at
  ) VALUES (
    v_company_uuid,
    v_employee_uuid,
    v_status,
    CASE WHEN FOUND THEN v_last.type ELSE NULL END,
    CASE WHEN FOUND THEN v_last.id::text ELSE NULL END,
    CASE WHEN FOUND THEN COALESCE(v_last.timestamp, v_last.created_at) ELSE NULL END,
    now(),
    COALESCE(NULLIF(btrim(p_source), ''), 'time_record_insert'),
    1,
    1,
    COALESCE(NULLIF(btrim(p_source), ''), 'time_record_insert'),
    v_effective_event_at
  )
  ON CONFLICT (company_id, employee_id) DO UPDATE SET
    operational_status = EXCLUDED.operational_status,
    last_punch_type = EXCLUDED.last_punch_type,
    last_punch_record_id = EXCLUDED.last_punch_record_id,
    last_punch_at = EXCLUDED.last_punch_at,
    updated_at = EXCLUDED.updated_at,
    last_update_source = EXCLUDED.last_update_source,
    state_version = s.state_version + 1,
    last_event_sequence = COALESCE(s.last_event_sequence, 0) + 1,
    state_source = EXCLUDED.state_source,
    last_event_at = GREATEST(
      COALESCE(EXCLUDED.last_event_at, s.last_event_at),
      COALESCE(s.last_event_at, EXCLUDED.last_event_at)
    );
END;
$$;


