--
-- Name: refresh_current_operational_state_rpc(text, text, text, timestamp with time zone, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_current_operational_state_rpc(p_company_id text, p_employee_id text, p_source text DEFAULT 'replay'::text, p_event_at timestamp with time zone DEFAULT now(), p_force boolean DEFAULT false, p_correlation_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sess├úo inv├ílida' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id::text = auth.uid()::text
      AND u.company_id::text = btrim(p_company_id)
      AND (
        u.id::text = btrim(p_employee_id)
        OR COALESCE(lower(u.role::text), '') IN ('admin', 'hr', 'supervisor')
      )
  ) THEN
    RAISE EXCEPTION 'Sem permiss├úo para atualizar estado operacional' USING ERRCODE = '42501';
  END IF;
  PERFORM public.refresh_current_operational_state(
    p_company_id,
    p_employee_id,
    p_source,
    p_event_at,
    p_force,
    p_correlation_id
  );
END;
$$;


