--
-- Name: rep_afd_canonical_11_digits(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_afd_canonical_11_digits(raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  d_raw text;
  d_strip text;
  i int;
  cand text;
BEGIN
  d_raw := public.rep_normalize_document_digits(raw);
  IF length(d_raw) = 0 THEN
    RETURN NULL;
  END IF;

  IF length(d_raw) <= 11 THEN
    IF length(d_raw) = 11 AND public.rep_validate_pis_pasep_11_digits(d_raw) THEN
      RETURN d_raw;
    END IF;
    IF length(d_raw) = 10 AND public.rep_validate_pis_pasep_11_digits('0' || d_raw) THEN
      RETURN '0' || d_raw;
    END IF;
    RETURN lpad(d_raw, 11, '0');
  END IF;

  IF length(d_raw) <= 14 THEN
    d_strip := regexp_replace(d_raw, '^0+', '');
    IF d_strip = '' THEN
      d_strip := '0';
    END IF;

    IF length(d_strip) = 11 AND public.rep_validate_pis_pasep_11_digits(d_strip) THEN
      RETURN d_strip;
    END IF;

    IF length(d_strip) = 11 AND NOT public.rep_validate_pis_pasep_11_digits(d_strip) THEN
      RETURN right(d_raw, 11);
    END IF;

    IF length(d_strip) = 10 AND public.rep_validate_pis_pasep_11_digits('0' || d_strip) THEN
      RETURN '0' || d_strip;
    END IF;

    IF length(d_strip) >= 12 AND length(d_strip) <= 14 THEN
      FOR i IN 1..(length(d_strip) - 10) LOOP
        cand := substring(d_strip from i for 11);
        IF public.rep_validate_pis_pasep_11_digits(cand) THEN
          RETURN cand;
        END IF;
      END LOOP;
    END IF;

    FOR i IN 1..(length(d_raw) - 10) LOOP
      cand := substring(d_raw from i for 11);
      IF public.rep_validate_pis_pasep_11_digits(cand) THEN
        RETURN cand;
      END IF;
    END LOOP;

    RETURN right(d_raw, 11);
  END IF;

  FOR i IN 1..(length(d_raw) - 10) LOOP
    cand := substring(d_raw from i for 11);
    IF public.rep_validate_pis_pasep_11_digits(cand) THEN
      RETURN cand;
    END IF;
  END LOOP;

  RETURN left(d_raw, 11);
END;
$$;


ALTER FUNCTION public.rep_afd_canonical_11_digits(raw text) OWNER TO postgres;

--
-- Name: FUNCTION rep_afd_canonical_11_digits(raw text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_afd_canonical_11_digits(raw text) IS 'Blob PIS/CPF AFD ÔåÆ 11 d├¡gitos (entrada via rep_normalize_document_digits); janelas DV PIS; legado Ôëñ14 / >14.';


--
-- Name: rep_afd_identifier_blob_from_compact_line(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_afd_identifier_blob_from_compact_line(p_line text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  s text;
  m text[];
BEGIN
  s := regexp_replace(btrim(COALESCE(p_line, '')), '\s+', '', 'g');
  IF length(s) < 24 THEN
    RETURN NULL;
  END IF;
  -- Tipo 3/7 (Portaria): 10.┬║ car├ícter ├® 3 ou 7.
  IF length(s) >= 23 AND substring(s FROM 10 FOR 1) ~ '[37]' AND s ~ '^\d{9}[37]\d{14,}' THEN
    m := regexp_match(s, '^(\d{9})([37])(\d{8})(\d{6})(\d{10,32})');
    IF m IS NOT NULL AND coalesce(array_length(m, 1), 0) >= 5 THEN
      RETURN m[5];
    END IF;
  END IF;
  -- Legada: NSR(9)+DDMMAAAA(8)+HHMMSS(6)+ident(10ÔÇô32) sem tipo entre NSR e data.
  IF length(s) >= 33 THEN
    m := regexp_match(s, '^(\d{9})(\d{8})(\d{6})(\d{10,32})');
    IF m IS NOT NULL AND coalesce(array_length(m, 1), 0) >= 4 THEN
      RETURN m[4];
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.rep_afd_identifier_blob_from_compact_line(p_line text) OWNER TO postgres;

--
-- Name: FUNCTION rep_afd_identifier_blob_from_compact_line(p_line text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_afd_identifier_blob_from_compact_line(p_line text) IS 'Campo identificador 10ÔÇô32 d├¡gitos: linha tipo 3/7 ou linha legada sem tipo entre NSR e data.';


