--
-- Name: rep_classify_promotion_sql_error(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_classify_promotion_sql_error(p_sqlstate text, p_message text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN COALESCE(p_message, '') ILIKE '%Sequ├¬ncia de ponto inv├ílida%'
      OR COALESCE(p_message, '') ILIKE '%sequ├¬ncia de ponto inv├ílida%'
      OR COALESCE(p_sqlstate, '') = '23514'
    THEN 'invalid_sequence'
    WHEN COALESCE(p_message, '') ILIKE '%PERIODO_FECHADO%'
      OR COALESCE(p_message, '') ILIKE '%folha j├í fechada%'
      OR COALESCE(p_message, '') ILIKE '%per├¡odo fechado%'
    THEN 'closed_period'
    WHEN COALESCE(p_message, '') ILIKE '%Portaria 671%'
      OR COALESCE(p_message, '') ILIKE '%Altera├º├úo de registro de ponto n├úo permitida%'
      OR COALESCE(p_message, '') ILIKE '%n├úo permitida (Portaria%'
    THEN 'protected_timesheet'
    WHEN COALESCE(p_message, '') ILIKE '%NSR j├í importado%'
      OR COALESCE(p_sqlstate, '') = '23505'
    THEN 'duplicate_nsr'
    WHEN COALESCE(p_message, '') ILIKE '%user_not_found%'
      OR COALESCE(p_message, '') ILIKE '%sem cadastro%'
    THEN 'missing_user'
    ELSE 'unknown'
  END;
$$;


