--
-- Name: rep_compact_afd_line_from_punch_raw(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_compact_afd_line_from_punch_raw(p_raw jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  cur jsonb;
  j jsonb;
  i int;
  s text;
BEGIN
  IF p_raw IS NULL OR jsonb_typeof(p_raw) <> 'object' THEN
    RETURN NULL;
  END IF;
  cur := p_raw;
  FOR i IN 1..5 LOOP
    IF jsonb_typeof(cur) <> 'object' OR NOT (cur ? 'raw') THEN
      EXIT;
    END IF;
    j := cur->'raw';
    IF jsonb_typeof(j) = 'string' THEN
      s := NULLIF(btrim(j #>> '{}'), '');
      IF s IS NOT NULL THEN
        RETURN s;
      END IF;
      EXIT;
    ELSIF jsonb_typeof(j) = 'object' THEN
      cur := j;
    ELSE
      EXIT;
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;


