--
-- Name: rep_compute_punch_hash(uuid, text, timestamp with time zone, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_compute_punch_hash(p_rep_device_id uuid, p_pis text, p_data_hora timestamp with time zone, p_nsr bigint) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT encode(
    extensions.digest(
      convert_to(
        concat_ws(
          '|',
          COALESCE(p_rep_device_id::text, ''),
          COALESCE(public.rep_afd_canonical_11_digits(p_pis), ''),
          COALESCE(
            to_char(timezone('UTC', p_data_hora), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            ''
          ),
          COALESCE(p_nsr::text, '')
        ),
        'UTF8'
      ),
      'sha256'::text
    ),
    'hex'
  );
$$;


