COMMENT ON FUNCTION public.rep_compute_punch_hash(p_rep_device_id uuid, p_pis text, p_data_hora timestamp with time zone, p_nsr bigint) IS 'SHA-256 hex (pgcrypto em extensions); alinhado ao agente REP.';


--
-- Name: rep_count_users_matching_direct_11_digits(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_count_users_matching_direct_11_digits(p_company_id text, p_document text) RETURNS bigint
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cid text;
  d text;
  v_n bigint;
BEGIN
  v_cid := btrim(COALESCE(p_company_id, ''));
  IF v_cid = '' THEN
    RETURN 0;
  END IF;

  d := public.rep_normalize_document_digits(COALESCE(p_document, ''));
  IF length(d) <> 11 THEN
    RETURN 0;
  END IF;

  SELECT COUNT(DISTINCT u.id) INTO v_n
  FROM public.users u
  WHERE btrim(u.company_id::text) = v_cid
    AND (
      public.rep_afd_canonical_11_digits(u.cpf) = d
      OR public.rep_afd_canonical_11_digits(u.pis_pasep) = d
    );

  RETURN COALESCE(v_n, 0);
END;
$$;


