-- Name: FUNCTION rep_count_users_matching_direct_11_digits(p_company_id text, p_document text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_count_users_matching_direct_11_digits(p_company_id text, p_document text) IS 'Conta colaboradores com CPF/PIS can├│nico igual ao documento 11 d├¡gitos (m├®tricas / ambiguidade).';


--
-- Name: rep_derive_matricula_from_afd_11(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_derive_matricula_from_afd_11(raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  d_raw text;
  d text;
  m text[];
  stripped text;
BEGIN
  d_raw := regexp_replace(COALESCE(raw, ''), '\D', '', 'g');
  IF length(d_raw) = 0 THEN
    RETURN NULL;
  END IF;

  IF length(d_raw) <= 11 THEN
    d := lpad(d_raw, 11, '0');
  ELSIF length(d_raw) <= 14 THEN
    d := right(d_raw, 11);
  ELSE
    d := left(d_raw, 11);
  END IF;

  IF length(d) <> 11 THEN
    RETURN NULL;
  END IF;

  m := regexp_match(d, '^0{3,}([1-9]\d{0,8})$');
  IF m IS NOT NULL THEN
    RETURN m[1];
  END IF;

  IF d ~ '^0{3,}' THEN
    stripped := regexp_replace(d, '^0+', '');
    IF length(stripped) >= 4 AND length(stripped) <= 9 AND stripped ~ '^[1-9]' THEN
      RETURN stripped;
    END IF;
  END IF;

  RETURN NULL;
END;
$_$;


ALTER FUNCTION public.rep_derive_matricula_from_afd_11(raw text) OWNER TO postgres;

--
-- Name: FUNCTION rep_derive_matricula_from_afd_11(raw text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_derive_matricula_from_afd_11(raw text) IS 'Deriva crach├í do blob PIS/CPF AFD (11 posi├º├Áes). Entrada 12ÔÇô14 d├¡gitos: usa os ├║ltimos 11, como o parser TS.';


--
-- Name: rep_effective_valid_pis_11_from_punch_raw(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_effective_valid_pis_11_from_punch_raw(p_raw_data jsonb, p_pis text, p_cpf text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_can text;
  cand text;
  inner_obj jsonb;
  deep jsonb;
  line text;
  blob text;
BEGIN
  v_can := public.rep_afd_canonical_11_digits(
    COALESCE(nullif(trim(COALESCE(p_pis, '')), ''), nullif(trim(COALESCE(p_cpf, '')), ''), '')
  );
  IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
    RETURN v_can;
  END IF;

  IF p_raw_data IS NULL OR jsonb_typeof(p_raw_data) <> 'object' THEN
    RETURN NULL;
  END IF;

  cand := nullif(trim(p_raw_data->>'cpfOuPis'), '');
  IF cand IS NOT NULL THEN
    v_can := public.rep_afd_canonical_11_digits(cand);
    IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
      RETURN v_can;
    END IF;
  END IF;

  cand := nullif(trim(p_raw_data->>'pis'), '');
  IF cand IS NOT NULL THEN
    v_can := public.rep_afd_canonical_11_digits(cand);
    IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
      RETURN v_can;
    END IF;
  END IF;

  IF p_raw_data ? 'raw' AND jsonb_typeof(p_raw_data->'raw') = 'object' THEN
    inner_obj := p_raw_data->'raw';

    cand := nullif(trim(inner_obj->>'cpfOuPis'), '');
    IF cand IS NOT NULL THEN
      v_can := public.rep_afd_canonical_11_digits(cand);
      IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
        RETURN v_can;
      END IF;
    END IF;

    cand := nullif(trim(inner_obj->>'pis'), '');
    IF cand IS NOT NULL THEN
      v_can := public.rep_afd_canonical_11_digits(cand);
      IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
        RETURN v_can;
      END IF;
    END IF;

    line := NULL;
    IF inner_obj ? 'raw' THEN
      IF jsonb_typeof(inner_obj->'raw') = 'string' THEN
        line := nullif(btrim(inner_obj->>'raw'), '');
      ELSIF jsonb_typeof(inner_obj->'raw') = 'object' THEN
        deep := inner_obj->'raw';

        cand := nullif(trim(deep->>'cpfOuPis'), '');
        IF cand IS NOT NULL THEN
          v_can := public.rep_afd_canonical_11_digits(cand);
          IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
            RETURN v_can;
          END IF;
        END IF;

        cand := nullif(trim(deep->>'pis'), '');
        IF cand IS NOT NULL THEN
          v_can := public.rep_afd_canonical_11_digits(cand);
          IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
            RETURN v_can;
          END IF;
        END IF;

        line := nullif(btrim(deep->>'raw'), '');
      END IF;
    END IF;

  ELSIF p_raw_data ? 'raw' AND jsonb_typeof(p_raw_data->'raw') = 'string' THEN
    line := nullif(btrim(p_raw_data->>'raw'), '');
  ELSE
    line := NULL;
  END IF;

  IF line IS NOT NULL THEN
    blob := public.rep_afd_identifier_blob_from_compact_line(line);
    IF blob IS NOT NULL THEN
      v_can := public.rep_afd_canonical_11_digits(blob);
      IF v_can IS NOT NULL AND public.rep_validate_pis_pasep_11_digits(v_can) THEN
        RETURN v_can;
      END IF;
      v_can := public.rep_unique_valid_pis_sliding_in_blob(blob);
      IF v_can IS NOT NULL THEN
        RETURN v_can;
      END IF;
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.rep_effective_valid_pis_11_from_punch_raw(p_raw_data jsonb, p_pis text, p_cpf text) OWNER TO postgres;

--
-- Name: FUNCTION rep_effective_valid_pis_11_from_punch_raw(p_raw_data jsonb, p_pis text, p_cpf text); Type: COMMENT; Schema: public; Owner: postgres
--

