--
-- Name: rep_emit_rep_match_metrics(text, text, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_emit_rep_match_metrics(p_context text, p_company_id text, p_total integer, p_strong integer, p_weak integer, p_direct integer, p_unresolved integer, p_ambiguous integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_total IS NULL OR p_total <= 0 THEN
    RETURN;
  END IF;
  RAISE LOG '[REP MATCH METRICS] %', jsonb_build_object(
    'context', p_context,
    'company_id', p_company_id,
    'total_processed', p_total,
    'strong_match', COALESCE(p_strong, 0),
    'weak_match', COALESCE(p_weak, 0),
    'direct_no_dv_match', COALESCE(p_direct, 0),
    'unresolved', COALESCE(p_unresolved, 0),
    'ambiguous', COALESCE(p_ambiguous, 0)
  );
END;
$$;


ALTER FUNCTION public.rep_emit_rep_match_metrics(p_context text, p_company_id text, p_total integer, p_strong integer, p_weak integer, p_direct integer, p_unresolved integer, p_ambiguous integer) OWNER TO postgres;

--
-- Name: FUNCTION rep_emit_rep_match_metrics(p_context text, p_company_id text, p_total integer, p_strong integer, p_weak integer, p_direct integer, p_unresolved integer, p_ambiguous integer); Type: COMMENT; Schema: public; Owner: postgres
--

