--
-- Name: rep_existing_types_operational_journey(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_existing_types_operational_journey(p_user_id uuid, p_company_id uuid, p_instant timestamp with time zone) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    array_agg(tr.type ORDER BY COALESCE(tr.timestamp, tr.created_at), tr.id),
    ARRAY[]::text[]
  )
  FROM public.time_records tr
  WHERE tr.user_id = p_user_id
    AND tr.company_id = p_company_id
    AND public.time_record_operational_date_sp(
      p_user_id,
      p_company_id,
      COALESCE(tr.timestamp, tr.created_at)
    ) = public.time_record_operational_date_sp(p_user_id, p_company_id, p_instant);
$$;


ALTER FUNCTION public.rep_existing_types_operational_journey(p_user_id uuid, p_company_id uuid, p_instant timestamp with time zone) OWNER TO postgres;

--
-- Name: rep_ignore_punch_logs(text, bigint[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_ignore_punch_logs(p_company_id text, p_nsr_list bigint[], p_ignored_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET row_security TO 'off'
    AS $$
DECLARE
  v_updated INTEGER := 0;
BEGIN
  UPDATE public.rep_punch_logs
  SET 
    ignored = TRUE,
    ignored_at = NOW(),
    ignored_by = p_ignored_by
  WHERE company_id = p_company_id
    AND nsr = ANY(p_nsr_list)
    AND ignored = FALSE;
  
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'success', TRUE,
    'ignored_count', v_updated
  );
END;
$$;


ALTER FUNCTION public.rep_ignore_punch_logs(p_company_id text, p_nsr_list bigint[], p_ignored_by uuid) OWNER TO postgres;

