-- Name: FUNCTION rep_punch_logs_sync_unresolved_quarantine(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_punch_logs_sync_unresolved_quarantine() IS 'Mant├®m rep_unresolved_punches alinhada a rep_punch_logs; company_id uuid nativo.';


--
-- Name: rep_register_punch(text, text, text, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_register_punch(p_user_id text, p_company_id text, p_type text, p_method text, p_record_id text DEFAULT NULL::text, p_location jsonb DEFAULT NULL::jsonb, p_photo_url text DEFAULT NULL::text, p_source text DEFAULT 'web'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_nsr BIGINT;
  v_previous_hash TEXT;
  v_payload TEXT;
  v_hash TEXT;
  v_ts TIMESTAMPTZ;
  v_record RECORD;
  v_receipt_id UUID;
  v_company_uuid uuid;
  v_user_uuid uuid;
BEGIN
  SET LOCAL row_security TO off;

  v_company_uuid := NULLIF(btrim(COALESCE(p_company_id, '')), '')::uuid;
  v_user_uuid := NULLIF(btrim(COALESCE(p_user_id, '')), '')::uuid;

  IF v_user_uuid IS NULL THEN
    RAISE EXCEPTION 'user_id inv├ílido (UUID esperado).' USING ERRCODE = '22P02';
  END IF;

  IF v_company_uuid IS NULL THEN
    RAISE EXCEPTION 'company_id inv├ílido (UUID esperado).' USING ERRCODE = '22P02';
  END IF;

  IF auth.uid() IS DISTINCT FROM v_user_uuid THEN
    RAISE EXCEPTION 'N├úo autorizado a registrar ponto para outro usu├írio.'
      USING ERRCODE = '42501';
  END IF;

  v_ts := NOW();

  VALUES (v_company_uuid, 1)
  ON CONFLICT (company_id) DO UPDATE
  SET current_nsr = public.time_nsr_sequence.current_nsr + 1, updated_at = NOW()
  RETURNING current_nsr INTO v_nsr;

  v_previous_hash := (
    SELECT tr.hash
    FROM public.time_records tr
    WHERE tr.company_id = v_company_uuid
      AND tr.nsr IS NOT NULL
    ORDER BY tr.nsr DESC
    LIMIT 1
  );

  v_previous_hash := COALESCE(v_previous_hash, '0');
  v_payload := v_user_uuid::text || '|' || v_ts::text || '|' || v_nsr::text || '|' || v_previous_hash;
  v_hash := rep_sha256(v_payload);

    id, user_id, company_id, type, method,
    location, photo_url, source, timestamp,
    nsr, hash, previous_hash
  ) VALUES (
    COALESCE(NULLIF(trim(p_record_id), ''), gen_random_uuid()::text),
    v_user_uuid,
    v_company_uuid,
    p_type,
    p_method,
    p_location,
    p_photo_url,
    p_source,
    v_ts,
    v_nsr,
    v_hash,
    v_previous_hash
  )
  RETURNING * INTO v_record;

  VALUES (
    ((v_record.id)::text)::uuid,
    v_company_uuid,
    v_user_uuid,
    v_nsr,
    jsonb_build_object(
      'nsr', v_nsr,
      'data', to_char(v_ts AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY'),
      'hora', to_char(v_ts AT TIME ZONE 'America/Sao_Paulo', 'HH24:MI:SS'),
      'hash', v_hash,
      'tipo', p_type
    )
  )
  RETURNING id INTO v_receipt_id;

  RETURN jsonb_build_object(
    'id', v_record.id,
    'nsr', v_nsr,
    'hash', v_hash,
    'previous_hash', v_previous_hash,
    'timestamp', v_ts,
    'receipt_id', v_receipt_id
  );
END;
$$;


