--
-- Name: rep_resolve_punch_type_operational(uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_resolve_punch_type_operational(p_user_id uuid, p_company_id uuid, p_instant timestamp with time zone, p_tipo_marcacao text DEFAULT NULL::text) RETURNS TABLE(resolved_type text, is_late boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_marc text;
  v_existing text[];
  v_interp jsonb;
  v_type text;
  v_late boolean := false;
BEGIN
  v_marc := UPPER(LEFT(COALESCE(NULLIF(trim(p_tipo_marcacao), ''), 'E'), 1));
  IF v_marc NOT IN ('E', 'S', 'P', 'B') THEN
    v_marc := 'B';
  END IF;

  IF v_marc IN ('S', 'P')
     AND p_tipo_marcacao IS NOT NULL
     AND trim(p_tipo_marcacao) <> ''
     AND lower(p_tipo_marcacao) NOT IN ('batida', 'b', 'e') THEN
    v_type := CASE v_marc
      WHEN 'S' THEN 'saida'
      WHEN 'P' THEN 'intervalo_saida'
      ELSE 'entrada'
    END;
  ELSE
    v_existing := public.rep_existing_types_operational_journey(p_user_id, p_company_id, p_instant);
    v_interp := public.interpret_punch_by_schedule(p_user_id, p_company_id, p_instant, v_existing);
    v_type := COALESCE(v_interp->>'type', public.rep_journey_type_for_position(COALESCE(array_length(v_existing, 1), 0)));
    v_late := COALESCE((v_interp->>'is_late')::boolean, false);
  END IF;

  resolved_type := replace(replace(lower(trim(v_type)), 'sa├¡da', 'saida'), 'pausa', 'intervalo_saida');
  is_late := v_late;
  RETURN NEXT;
END;
$$;


