--
-- Name: rep_resolve_user_id_rep_blob_unique(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_resolve_user_id_rep_blob_unique(p_company_id text, p_id_blob_d text) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cid text;
  v_n bigint;
  v_uid uuid;
BEGIN
  IF p_id_blob_d IS NULL OR length(p_id_blob_d) < 8 THEN
    RETURN NULL;
  END IF;

  v_cid := btrim(COALESCE(p_company_id, ''));
  IF v_cid = '' THEN
    RETURN NULL;
  END IF;

  SELECT COUNT(DISTINCT u.id) INTO v_n
  FROM public.users u
  CROSS JOIN LATERAL (
    SELECT regexp_replace(COALESCE(u.numero_identificador, ''), '\D', '', 'g') AS idg
  ) x
  WHERE btrim(u.company_id::text) = v_cid
    AND length(x.idg) >= 8
    AND (
      p_id_blob_d LIKE concat(x.idg, '%')
      OR (length(x.idg) >= 10 AND strpos(p_id_blob_d, x.idg) > 0)
    );

  IF v_n <> 1 THEN
    RETURN NULL;
  END IF;

  SELECT u.id INTO v_uid
  FROM public.users u
  CROSS JOIN LATERAL (
    SELECT regexp_replace(COALESCE(u.numero_identificador, ''), '\D', '', 'g') AS idg
  ) x
  WHERE btrim(u.company_id::text) = v_cid
    AND length(x.idg) >= 8
    AND (
      p_id_blob_d LIKE concat(x.idg, '%')
      OR (length(x.idg) >= 10 AND strpos(p_id_blob_d, x.idg) > 0)
    )
  ORDER BY length(x.idg) DESC, u.id
  LIMIT 1;

  RETURN v_uid;
END;
$$;


