CREATE FUNCTION public.rep_sha256(input_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  RETURN encode(sha256(input_text::bytea), 'hex');
END;
$$;


ALTER FUNCTION public.rep_sha256(input_text text) OWNER TO postgres;

--
-- Name: rep_unique_valid_pis_sliding_in_blob(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_unique_valid_pis_sliding_in_blob(p_blob text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  d text;
  n int;
  i int;
  w text;
  hit1 text := NULL;
  hit2 text := NULL;
BEGIN
  d := public.rep_normalize_document_digits(COALESCE(p_blob, ''));
  n := length(d);
  IF n < 11 THEN
    RETURN NULL;
  END IF;

  FOR i IN 1..(n - 10) LOOP
    w := substring(d from i for 11);
    IF public.rep_validate_pis_pasep_11_digits(w) THEN
      IF hit1 IS NULL THEN
        hit1 := w;
      ELSIF hit1 IS DISTINCT FROM w THEN
        hit2 := w;
        EXIT;
      END IF;
    END IF;
  END LOOP;

  IF hit1 IS NOT NULL AND hit2 IS NULL THEN
    RETURN hit1;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.rep_unique_valid_pis_sliding_in_blob(p_blob text) OWNER TO postgres;

--
-- Name: FUNCTION rep_unique_valid_pis_sliding_in_blob(p_blob text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_unique_valid_pis_sliding_in_blob(p_blob text) IS 'Blob s├│ d├¡gitos: se existir exactamente um PIS/PASEP 11 com DV v├ílido em janela deslizante, devolve-o; sen├úo NULL.';


--
-- Name: rep_validate_cpf_11_digits(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_validate_cpf_11_digits(p_digits text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  i int;
  s int;
  r int;
  dv1 int;
  dv2 int;
BEGIN
  IF p_digits !~ '^\d{11}$' THEN
    RETURN FALSE;
  END IF;
  IF p_digits ~ '^(\d)\1{10}$' THEN
    RETURN FALSE;
  END IF;

  s := 0;
  FOR i IN 1..9 LOOP
    s := s + (substring(p_digits from i for 1))::int * (11 - i);
  END LOOP;
  r := s % 11;
  dv1 := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
  IF dv1 <> (substring(p_digits from 10 for 1))::int THEN
    RETURN FALSE;
  END IF;

  s := 0;
  FOR i IN 1..10 LOOP
    s := s + (substring(p_digits from i for 1))::int * (12 - i);
  END LOOP;
  r := s % 11;
  dv2 := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
  RETURN dv2 = (substring(p_digits from 11 for 1))::int;
END;
$_$;


ALTER FUNCTION public.rep_validate_cpf_11_digits(p_digits text) OWNER TO postgres;

--
-- Name: FUNCTION rep_validate_cpf_11_digits(p_digits text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_validate_cpf_11_digits(p_digits text) IS 'DV CPF (11 d├¡gitos), rejeita sequ├¬ncias repetidas; usado no match REP.';


--
-- Name: rep_validate_pis_pasep_11_digits(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rep_validate_pis_pasep_11_digits(p_digits text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  s int := 0;
  r int;
  dv int;
  w int[] := ARRAY[3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
  i int;
BEGIN
  IF p_digits !~ '^\d{11}$' THEN
    RETURN FALSE;
  END IF;
  FOR i IN 1..10 LOOP
    s := s + w[i] * (substring(p_digits from i for 1))::int;
  END LOOP;
  r := s % 11;
  dv := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
  RETURN dv = (substring(p_digits from 11 for 1))::int;
END;
$_$;


ALTER FUNCTION public.rep_validate_pis_pasep_11_digits(p_digits text) OWNER TO postgres;

--
-- Name: FUNCTION rep_validate_pis_pasep_11_digits(p_digits text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rep_validate_pis_pasep_11_digits(p_digits text) IS 'DV PIS/PASEP (NIS) 11 d├¡gitos ÔÇö pesos 3,2,9,8,7,6,5,4,3,2; uso interno em rep_afd_canonical_11_digits.';


--
-- Name: resolve_operational_date_sp(timestamp with time zone, time without time zone, time without time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_operational_date_sp(p_instant timestamp with time zone, p_schedule_entrada time without time zone, p_schedule_saida_final time without time zone, p_tolerance_min integer DEFAULT 60) RETURNS date
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_civil date;
  v_yesterday date;
  v_time_min integer;
  v_cutoff integer;
BEGIN
  v_civil := (p_instant AT TIME ZONE 'America/Sao_Paulo')::date;
  v_yesterday := v_civil - 1;
  v_time_min := EXTRACT(HOUR FROM (p_instant AT TIME ZONE 'America/Sao_Paulo'))::int * 60
              + EXTRACT(MINUTE FROM (p_instant AT TIME ZONE 'America/Sao_Paulo'))::int;

  IF p_schedule_entrada IS NULL OR p_schedule_saida_final IS NULL THEN
    RETURN v_civil;
  END IF;

  IF NOT public.is_night_shift_schedule(p_schedule_entrada, p_schedule_saida_final) THEN
    RETURN v_civil;
  END IF;

  v_cutoff := public.night_journey_post_midnight_cutoff_minutes(
    p_schedule_entrada,
    p_schedule_saida_final,
    p_tolerance_min
  );

  IF v_time_min <= v_cutoff THEN
    RETURN v_yesterday;
  END IF;

  RETURN v_civil;
END;
$$;


ALTER FUNCTION public.resolve_operational_date_sp(p_instant timestamp with time zone, p_schedule_entrada time without time zone, p_schedule_saida_final time without time zone, p_tolerance_min integer) OWNER TO postgres;

