-- Name: FUNCTION resolve_operational_date_sp(p_instant timestamp with time zone, p_schedule_entrada time without time zone, p_schedule_saida_final time without time zone, p_tolerance_min integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.resolve_operational_date_sp(p_instant timestamp with time zone, p_schedule_entrada time without time zone, p_schedule_saida_final time without time zone, p_tolerance_min integer) IS 'Data operacional de uma batida com escala noturna (refer├¬ncia = data da primeira entrada).';


--
-- Name: seed_all_missing_employee_shift_schedules(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seed_all_missing_employee_shift_schedules() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  u RECORD;
  n INT := 0;
BEGIN
  FOR u IN
    SELECT id FROM public.users
    WHERE schedule_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.employee_shift_schedule e WHERE e.employee_id = users.id
      )
  LOOP
    PERFORM public.seed_employee_shift_schedule_from_user_schedule(u.id);
    n := n + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'users_processed', n);
END;
$$;


ALTER FUNCTION public.seed_all_missing_employee_shift_schedules() OWNER TO postgres;

--
-- Name: seed_employee_shift_schedule_from_user_schedule(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seed_employee_shift_schedule_from_user_schedule(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_company_id TEXT;
  v_schedule_id UUID;
  v_shift_id UUID;
  v_days INT[];
  d INT;
  v_ws_json JSONB;
  v_ins INT := 0;
BEGIN
  v_company_id := (
    SELECT u.company_id::TEXT FROM public.users u WHERE u.id = p_employee_id LIMIT 1
  );
  v_schedule_id := (
    SELECT u.schedule_id FROM public.users u WHERE u.id = p_employee_id LIMIT 1
  );

  IF v_company_id IS NULL OR v_schedule_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_schedule_on_user');
  END IF;

  IF EXISTS (SELECT 1 FROM public.employee_shift_schedule WHERE employee_id = p_employee_id LIMIT 1) THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'ess_already_exists');
  END IF;

  v_shift_id := (
    SELECT s.shift_id FROM public.schedules s WHERE s.id = v_schedule_id LIMIT 1
  );
  v_days := (
    SELECT COALESCE(s.days, ARRAY[1,2,3,4,5]::INT[])
    FROM public.schedules s
    WHERE s.id = v_schedule_id
    LIMIT 1
  );

  IF v_shift_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_shift_on_schedule');
  END IF;

  v_ws_json := (
    SELECT jsonb_build_object(
      'id', ws.id,
      'st', ws.start_time::time,
      'en', ws.end_time::time,
      'bs', ws.break_start_time::time,
      'be', ws.break_end_time::time,
      'tol', COALESCE(ws.tolerance_minutes, ws.tolerancia_entrada, 10)
    )
    FROM public.work_shifts ws
    WHERE ws.id = v_shift_id
    LIMIT 1
  );

  IF v_ws_json IS NULL OR (v_ws_json->>'id') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'work_shift_not_found');
  END IF;

  FOR d IN 0..6 LOOP
    IF d = ANY(v_days) THEN
        employee_id, company_id, day_of_week,
        shift_id, work_shift_id,
        is_day_off, is_workday,
        start_time, end_time, break_start, break_end, tolerance_minutes
      ) VALUES (
        p_employee_id, v_company_id, d,
        v_shift_id, v_shift_id,
        FALSE, TRUE,
        (v_ws_json->>'st')::time,
        (v_ws_json->>'en')::time,
        (v_ws_json->>'bs')::time,
        (v_ws_json->>'be')::time,
        (v_ws_json->>'tol')::int
      )
      ON CONFLICT (employee_id, day_of_week) DO UPDATE SET
        company_id = EXCLUDED.company_id,
        shift_id = EXCLUDED.shift_id,
        work_shift_id = EXCLUDED.work_shift_id,
        is_day_off = EXCLUDED.is_day_off,
        is_workday = EXCLUDED.is_workday,
        start_time = EXCLUDED.start_time,
        end_time = EXCLUDED.end_time,
        break_start = EXCLUDED.break_start,
        break_end = EXCLUDED.break_end,
        tolerance_minutes = EXCLUDED.tolerance_minutes,
        updated_at = NOW();
    ELSE
        employee_id, company_id, day_of_week,
        shift_id, work_shift_id,
        is_day_off, is_workday,
        start_time, end_time, break_start, break_end
      ) VALUES (
        p_employee_id, v_company_id, d,
        NULL, NULL,
        TRUE, FALSE,
        NULL, NULL, NULL, NULL
      )
      ON CONFLICT (employee_id, day_of_week) DO UPDATE SET
        company_id = EXCLUDED.company_id,
        shift_id = EXCLUDED.shift_id,
        work_shift_id = EXCLUDED.work_shift_id,
        is_day_off = EXCLUDED.is_day_off,
        is_workday = EXCLUDED.is_workday,
        start_time = EXCLUDED.start_time,
        end_time = EXCLUDED.end_time,
        break_start = EXCLUDED.break_start,
        break_end = EXCLUDED.break_end,
        updated_at = NOW();
    END IF;
    v_ins := v_ins + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'inserted_days', v_ins);
END;
$$;


ALTER FUNCTION public.seed_employee_shift_schedule_from_user_schedule(p_employee_id uuid) OWNER TO postgres;

--
-- Name: seed_escalas_padrao(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seed_escalas_padrao(p_company_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  WITH ins AS (
      id, company_id, name, tipo, dias_trabalho, dias_folga,
      days, descricao, ativo
    )
    SELECT
      gen_random_uuid(), p_company_id, '5x2 - Seg a Sex', 'FIXA', 5, 2,
      ARRAY[1, 2, 3, 4, 5], 'Segunda a Sexta trabalho, S├íbado e Domingo folga', true
    WHERE NOT EXISTS (
      SELECT 1 FROM public.schedules
      WHERE company_id = p_company_id AND name = '5x2 - Seg a Sex'
    )
    RETURNING id
  )
  SELECT ins.id, v.dow, v.tipo
  FROM ins
  CROSS JOIN (
    VALUES
      (0::smallint, 'FOLGA'::text),
      (1::smallint, 'TRABALHO'::text),
      (2::smallint, 'TRABALHO'::text),
      (3::smallint, 'TRABALHO'::text),
      (4::smallint, 'TRABALHO'::text),
      (5::smallint, 'TRABALHO'::text),
      (6::smallint, 'FOLGA'::text)
  ) AS v(dow, tipo);

  WITH ins AS (
      id, company_id, name, tipo, dias_trabalho, dias_folga,
      days, descricao, ativo
    )
    SELECT
      gen_random_uuid(), p_company_id, '6x1 - Rotativa', 'ROTATIVA', 6, 1,
      ARRAY[1, 2, 3, 4, 5, 6], '6 dias trabalho (segÔÇôs├íb), 1 folga (domingo no seed padr├úo)', true
    WHERE NOT EXISTS (
      SELECT 1 FROM public.schedules
      WHERE company_id = p_company_id AND name = '6x1 - Rotativa'
    )
    RETURNING id
  )
  SELECT ins.id, v.dow, v.tipo
  FROM ins
  CROSS JOIN (
    VALUES
      (0::smallint, 'FOLGA'::text),
      (1::smallint, 'TRABALHO'::text),
      (2::smallint, 'TRABALHO'::text),
      (3::smallint, 'TRABALHO'::text),
      (4::smallint, 'TRABALHO'::text),
      (5::smallint, 'TRABALHO'::text),
      (6::smallint, 'TRABALHO'::text)
  ) AS v(dow, tipo);

    id, company_id, name, tipo, dias_trabalho, dias_folga,
    days, descricao, ativo
  )
  SELECT
    gen_random_uuid(), p_company_id, '12x36', 'ROTATIVA', 1, 1,
    ARRAY[]::INTEGER[], 'Trabalha 12h, folga 36h - escala alternada', true
  WHERE NOT EXISTS (
    SELECT 1 FROM public.schedules
    WHERE company_id = p_company_id AND name = '12x36'
  );

    id, company_id, name, tipo, dias_trabalho, dias_folga,
    days, descricao, ativo
  )
  SELECT
    gen_random_uuid(), p_company_id, 'Escala Turno', 'PERSONALIZADA', 0, 0,
    ARRAY[]::INTEGER[], 'Escala definida pelo hor├írio vinculado ao colaborador', true
  WHERE NOT EXISTS (
    SELECT 1 FROM public.schedules
    WHERE company_id = p_company_id AND name = 'Escala Turno'
  );
END;
$$;


