ALTER FUNCTION public.sync_employees_on_user_delete() OWNER TO postgres;

--
-- Name: sync_user_to_employees(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_user_to_employees() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
BEGIN
  IF COALESCE(NEW.role, '') IN ('employee', 'admin', 'hr') THEN
      id, company_id, department_id, schedule_id, shift_id,
      nome, email, cargo, phone, cpf, status, created_at, updated_at
    )
    VALUES (
      NEW.id,
      NEW.company_id,
      NEW.department_id,
      NEW.schedule_id,
      NEW.shift_id,
      COALESCE(NEW.nome, ''),
      COALESCE(NEW.email, ''),
      COALESCE(NEW.cargo, 'Colaborador'),
      NEW.phone,
      NEW.cpf,
      COALESCE(NEW.status, 'active'),
      COALESCE(NEW.created_at, now()),
      COALESCE(NEW.updated_at, now())
    )
    ON CONFLICT (id) DO UPDATE SET
      company_id = EXCLUDED.company_id,
      department_id = EXCLUDED.department_id,
      schedule_id = EXCLUDED.schedule_id,
      shift_id = EXCLUDED.shift_id,
      nome = EXCLUDED.nome,
      email = EXCLUDED.email,
      cargo = EXCLUDED.cargo,
      phone = EXCLUDED.phone,
      cpf = EXCLUDED.cpf,
      status = EXCLUDED.status,
      updated_at = EXCLUDED.updated_at
    WHERE employees.company_id IS DISTINCT FROM EXCLUDED.company_id
       OR employees.department_id IS DISTINCT FROM EXCLUDED.department_id
       OR employees.schedule_id IS DISTINCT FROM EXCLUDED.schedule_id
       OR employees.shift_id IS DISTINCT FROM EXCLUDED.shift_id
       OR employees.nome IS DISTINCT FROM EXCLUDED.nome
       OR employees.email IS DISTINCT FROM EXCLUDED.email
       OR employees.cargo IS DISTINCT FROM EXCLUDED.cargo
       OR employees.phone IS DISTINCT FROM EXCLUDED.phone
       OR employees.cpf IS DISTINCT FROM EXCLUDED.cpf
       OR employees.status IS DISTINCT FROM EXCLUDED.status;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_user_to_employees() OWNER TO postgres;

--
-- Name: time_record_operational_date_sp(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.time_record_operational_date_sp(p_user_id uuid, p_company_id uuid, p_instant timestamp with time zone) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_civil date;
  v_yesterday date;
  v_js_dow int;
  v_prev_dow int;
  v_time_min int;
  v_shift_start time;
  v_shift_end time;
  v_tol int;
  v_cutoff int;
BEGIN
  v_civil := (p_instant AT TIME ZONE 'America/Sao_Paulo')::date;
  v_yesterday := v_civil - 1;
  v_js_dow := EXTRACT(dow FROM (p_instant AT TIME ZONE 'America/Sao_Paulo'))::int;
  v_prev_dow := CASE WHEN v_js_dow = 0 THEN 6 ELSE v_js_dow - 1 END;
  v_time_min := EXTRACT(HOUR FROM (p_instant AT TIME ZONE 'America/Sao_Paulo'))::int * 60
              + EXTRACT(MINUTE FROM (p_instant AT TIME ZONE 'America/Sao_Paulo'))::int;

  SELECT t.shift_start, t.shift_end, COALESCE(t.tol, 60)
  INTO v_shift_start, v_shift_end, v_tol
  FROM public.ess_day_shift_times(p_user_id, p_company_id::text, v_prev_dow) t
  LIMIT 1;

  IF v_shift_start IS NOT NULL AND v_shift_end IS NOT NULL
     AND public.is_night_shift_schedule(v_shift_start, v_shift_end) THEN
    v_cutoff := public.night_journey_post_midnight_cutoff_minutes(v_shift_start, v_shift_end, v_tol);
    IF v_time_min <= v_cutoff THEN
      RETURN v_yesterday;
    END IF;
  END IF;

  SELECT t.shift_start, t.shift_end, COALESCE(t.tol, 60)
  INTO v_shift_start, v_shift_end, v_tol
  FROM public.ess_day_shift_times(p_user_id, p_company_id::text, v_js_dow) t
  LIMIT 1;

  IF v_shift_start IS NOT NULL AND v_shift_end IS NOT NULL
     AND public.is_night_shift_schedule(v_shift_start, v_shift_end) THEN
    RETURN public.resolve_operational_date_sp(p_instant, v_shift_start, v_shift_end, v_tol);
  END IF;

  -- REP sem ESS: madrugada (at├® 12h) ap├│s batida >=21h no dia civil anterior.
  IF v_time_min <= 720 THEN
    IF EXISTS (
      SELECT 1
      FROM public.time_records tr
      WHERE tr.user_id::text = p_user_id::text
        AND tr.company_id::text = p_company_id::text
        AND (COALESCE(tr.source, '') = 'rep' OR COALESCE(tr.method, '') ILIKE '%rep%')
        AND (COALESCE(tr.timestamp, tr.created_at) AT TIME ZONE 'America/Sao_Paulo')::date = v_yesterday
        AND (
          EXTRACT(HOUR FROM COALESCE(tr.timestamp, tr.created_at) AT TIME ZONE 'America/Sao_Paulo')::int * 60
          + EXTRACT(MINUTE FROM COALESCE(tr.timestamp, tr.created_at) AT TIME ZONE 'America/Sao_Paulo')::int
        ) >= 21 * 60
    ) THEN
      RETURN v_yesterday;
    END IF;
  END IF;

  RETURN v_civil;
END;
$$;


ALTER FUNCTION public.time_record_operational_date_sp(p_user_id uuid, p_company_id uuid, p_instant timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION time_record_operational_date_sp(p_user_id uuid, p_company_id uuid, p_instant timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.time_record_operational_date_sp(p_user_id uuid, p_company_id uuid, p_instant timestamp with time zone) IS 'Data operacional: ESS noturna ÔåÆ fallback REP (madrugada ap├│s entrada >=21h ontem).';


--
-- Name: time_records_block_after_closure(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.time_records_block_after_closure() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id text;
  v_company_id text;
  v_ref_ts timestamptz;
  v_closed boolean;
  v_bypass text;
BEGIN
  v_bypass := COALESCE(current_setting('ponto.allow_closed_timesheet_write', true), '');
  IF v_bypass = '1' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    v_user_id := NEW.user_id::text;
    v_company_id := NEW.company_id::text;
    v_ref_ts := COALESCE(NEW.timestamp, NEW.created_at, NOW());
  ELSE
    v_user_id := OLD.user_id::text;
    v_company_id := OLD.company_id::text;
    v_ref_ts := COALESCE(OLD.timestamp, OLD.created_at, NOW());
  END IF;

  SELECT public.timesheet_is_closed_for_stamp(v_company_id, v_user_id, v_ref_ts)
  INTO v_closed;

  IF v_closed THEN
    RAISE EXCEPTION 'PERIODO_FECHADO'
      USING ERRCODE = 'check_violation',
        HINT = 'Folha j├í fechada para este colaborador no per├¡odo do registro.';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.time_records_block_after_closure() OWNER TO postgres;

--
-- Name: time_records_enforce_origin_and_rep_gps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.time_records_enforce_origin_and_rep_gps() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF COALESCE(NEW.source, '') ILIKE 'rep'
     OR COALESCE(NEW.method, '') ILIKE 'rep'
     OR COALESCE(NEW.source, '') = 'clock'
  THEN
    NEW.origin := COALESCE(NULLIF(TRIM(COALESCE(NEW.origin, '')), ''), 'rep');
    NEW.source_type := COALESCE(NULLIF(TRIM(COALESCE(NEW.source_type, '')), ''), 'control_id');
    NEW.latitude := NULL;
    NEW.longitude := NULL;
    NEW.accuracy := NULL;
  ELSE
    IF COALESCE(NEW.origin, '') = '' THEN
      NEW.origin := 'mobile';
    END IF;
    IF COALESCE(NEW.source_type, '') = '' THEN
      NEW.source_type := 'app';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.time_records_enforce_origin_and_rep_gps() OWNER TO postgres;

--
-- Name: time_records_enforce_punch_sequence(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.time_records_enforce_punch_sequence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_skip text;
  v_day date;
  v_last text;
  v_t text;
  r record;
  v_prev_inst timestamptz;
  v_prev_type text;
  v_gap_sec double precision;
  v_new_inst timestamptz;
  v_n int;
  v_m int;
  v_new_sandwich boolean;
  v_dup_thresh double precision;
  v_rep_like boolean;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;

  v_skip := NULLIF(trim(COALESCE(current_setting('ponto.skip_time_record_sequence_check', true), '')), '');
  IF v_skip = '1' THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.is_manual, false) THEN
    RETURN NEW;
  END IF;

  v_t := public.normalize_time_record_punch_type(NEW.type);
  IF v_t NOT IN ('entrada', 'saida', 'pausa') THEN
    RETURN NEW;
  END IF;

  v_day := public.time_record_operational_date_sp(NEW.user_id::uuid, NEW.company_id, COALESCE(NEW.timestamp, NEW.created_at, NOW()));
  v_new_inst := COALESCE(NEW.timestamp, NEW.created_at, NOW());

  v_rep_like := COALESCE(NEW.method, '') ILIKE 'rep'
    OR COALESCE(NEW.source, '') ILIKE 'rep'
    OR COALESCE(NEW.source, '') = 'clock';
  v_dup_thresh := CASE WHEN v_rep_like THEN 1::double precision ELSE 45::double precision END;

  IF v_t = 'entrada' THEN
    SELECT
      public.normalize_time_record_punch_type(tr.type),
      COALESCE(tr.timestamp, tr.created_at)
    INTO v_prev_type, v_prev_inst
    FROM public.time_records tr
    WHERE tr.user_id::text = NEW.user_id::text
      AND public.time_record_operational_date_sp(NEW.user_id::uuid, NEW.company_id, COALESCE(tr.timestamp, tr.created_at)) = v_day
      AND COALESCE(tr.timestamp, tr.created_at) < v_new_inst
    ORDER BY COALESCE(tr.timestamp, tr.created_at) DESC, tr.id DESC
    LIMIT 1;

    IF v_prev_type = 'entrada' THEN
      v_gap_sec := EXTRACT(EPOCH FROM (v_new_inst - v_prev_inst));
      IF v_gap_sec > v_dup_thresh THEN
        NEW.type := 'saida';
        NEW.raw_data := COALESCE(NEW.raw_data, '{}'::jsonb)
          || jsonb_build_object(
            'sequence_adjusted', true,
            'sequence_fix', 'entrada_duplicada_para_saida',
            'sequence_gap_seconds', round(v_gap_sec)::int
          );
        v_t := public.normalize_time_record_punch_type(NEW.type);
        RAISE LOG '[CALC FIX] entrada duplicada convertida em sa├¡da user=% gap_min=%',
          NEW.user_id, (v_gap_sec / 60.0);
      END IF;
    END IF;
  END IF;

  v_t := public.normalize_time_record_punch_type(NEW.type);

  IF v_t = 'entrada' THEN
    BEGIN
      PERFORM set_config('ponto.time_record_sequence_reconcile', '1', true);
      LOOP
        v_n := 0;
        v_m := 0;

        WITH day_rows AS (
          SELECT
            tr.id::text AS row_pk,
            COALESCE(tr.timestamp, tr.created_at) AS inst,
            public.normalize_time_record_punch_type(tr.type) AS typ,
            tr.id::text AS rid
          FROM public.time_records tr
          WHERE tr.user_id::text = NEW.user_id::text
            AND public.time_record_operational_date_sp(NEW.user_id::uuid, NEW.company_id, COALESCE(tr.timestamp, tr.created_at)) = v_day
          UNION ALL
          SELECT
            NULL::text AS row_pk,
            v_new_inst,
            v_t,
            COALESCE(NEW.id::text, '')
        ),
        ordered AS (
          SELECT
            row_pk,
            inst,
            typ,
            rid,
            lag(typ) OVER (ORDER BY inst ASC, rid ASC) AS prev_typ,
            lag(inst) OVER (ORDER BY inst ASC, rid ASC) AS prev_inst,
            lag(rid) OVER (ORDER BY inst ASC, rid ASC) AS prev_rid
          FROM day_rows
        )
        UPDATE public.time_records tr
        SET
          type = 'saida',
          raw_data = COALESCE(tr.raw_data, '{}'::jsonb)
            || jsonb_build_object(
              'sequence_adjusted', true,
              'sequence_fix', 'posterior_entrada_duplicada_para_saida',
              'sequence_gap_seconds', round(EXTRACT(EPOCH FROM (o.inst - o.prev_inst)))::int
            )
        FROM ordered o
        WHERE tr.id::text = o.row_pk
          AND o.row_pk IS NOT NULL
          AND o.typ = 'entrada'
          AND o.prev_typ = 'entrada'
          AND (
            EXTRACT(EPOCH FROM (o.inst - o.prev_inst)) > v_dup_thresh
            OR (o.inst = o.prev_inst AND o.prev_rid IS NOT NULL AND o.rid > o.prev_rid)
          );

        GET DIAGNOSTICS v_n = ROW_COUNT;

        WITH day_rows AS (
          SELECT
            tr.id::text AS row_pk,
            COALESCE(tr.timestamp, tr.created_at) AS inst,
            public.normalize_time_record_punch_type(tr.type) AS typ,
            tr.id::text AS rid
          FROM public.time_records tr
          WHERE tr.user_id::text = NEW.user_id::text
            AND public.time_record_operational_date_sp(NEW.user_id::uuid, NEW.company_id, COALESCE(tr.timestamp, tr.created_at)) = v_day
          UNION ALL
          SELECT
            NULL::text AS row_pk,
            v_new_inst,
            v_t,
            COALESCE(NEW.id::text, '')
        ),
        ordered AS (
          SELECT
            row_pk,
            inst,
            typ,
            lag(typ) OVER (ORDER BY inst ASC, rid ASC) AS prev_typ,
            lag(inst) OVER (ORDER BY inst ASC, rid ASC) AS prev_inst,
            lead(typ) OVER (ORDER BY inst ASC, rid ASC) AS next_typ
          FROM day_rows
        )
        UPDATE public.time_records tr
        SET
          type = 'saida',
          raw_data = COALESCE(tr.raw_data, '{}'::jsonb)
            || jsonb_build_object(
              'sequence_adjusted', true,
              'sequence_fix', 'entrada_intercalada_duplicada_para_saida',
              'sequence_gap_seconds', round(EXTRACT(EPOCH FROM (o.inst - o.prev_inst)))::int
            )
        FROM ordered o
        WHERE tr.id::text = o.row_pk
          AND o.row_pk IS NOT NULL
          AND o.typ = 'entrada'
          AND o.prev_typ = 'entrada'
          AND o.next_typ = 'entrada'
          AND EXTRACT(EPOCH FROM (o.inst - o.prev_inst)) <= 300;

        GET DIAGNOSTICS v_m = ROW_COUNT;

        IF v_t = 'entrada' AND v_n = 0 AND v_m = 0 THEN
          SELECT EXISTS (
            SELECT 1
            FROM (
              WITH day_rows AS (
                SELECT
                  tr.id::text AS row_pk,
                  COALESCE(tr.timestamp, tr.created_at) AS inst,
                  public.normalize_time_record_punch_type(tr.type) AS typ,
                  tr.id::text AS rid
                FROM public.time_records tr
                WHERE tr.user_id::text = NEW.user_id::text
                  AND public.time_record_operational_date_sp(NEW.user_id::uuid, NEW.company_id, COALESCE(tr.timestamp, tr.created_at)) = v_day
                UNION ALL
                SELECT
                  NULL::text AS row_pk,
                  v_new_inst,
                  v_t,
                  COALESCE(NEW.id::text, '')
              ),
              ordered AS (
                SELECT
                  row_pk,
                  inst,
                  typ,
                  lag(typ) OVER (ORDER BY inst ASC, rid ASC) AS prev_typ,
                  lag(inst) OVER (ORDER BY inst ASC, rid ASC) AS prev_inst,
                  lead(typ) OVER (ORDER BY inst ASC, rid ASC) AS next_typ
                FROM day_rows
              )
              SELECT 1
              FROM ordered o
              WHERE o.row_pk IS NULL
                AND o.typ = 'entrada'
                AND o.prev_typ = 'entrada'
                AND o.next_typ = 'entrada'
                AND EXTRACT(EPOCH FROM (o.inst - o.prev_inst)) <= 300
            ) x
          )
          INTO v_new_sandwich;

          IF v_new_sandwich THEN
            NEW.type := 'saida';
            NEW.raw_data := COALESCE(NEW.raw_data, '{}'::jsonb)
              || jsonb_build_object(
                'sequence_adjusted', true,
                'sequence_fix', 'entrada_intercalada_novo_para_saida'
              );
            EXIT;
          END IF;
        END IF;

        EXIT WHEN v_n = 0 AND v_m = 0;
      END LOOP;
      PERFORM set_config('ponto.time_record_sequence_reconcile', '0', true);
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('ponto.time_record_sequence_reconcile', '0', true);
      RAISE;
    END;
  END IF;

  v_t := public.normalize_time_record_punch_type(NEW.type);

  v_last := NULL;
  FOR r IN
    SELECT s.inst, s.typ
    FROM (
      SELECT
        COALESCE(tr.timestamp, tr.created_at) AS inst,
        public.normalize_time_record_punch_type(tr.type) AS typ,
        tr.id::text AS rid
      FROM public.time_records tr
      WHERE tr.user_id::text = NEW.user_id::text
        AND public.time_record_operational_date_sp(NEW.user_id::uuid, NEW.company_id, COALESCE(tr.timestamp, tr.created_at)) = v_day
      UNION ALL
      SELECT
        COALESCE(NEW.timestamp, NEW.created_at, NOW()),
        v_t,
        COALESCE(NEW.id::text, '')
    ) s
    WHERE s.typ IN ('entrada', 'saida', 'pausa')
    ORDER BY s.inst ASC, s.rid ASC
  LOOP
    v_t := r.typ;

    IF v_last IS NULL THEN
      IF v_t <> 'entrada' THEN
        RAISE EXCEPTION 'Sequ├¬ncia de ponto inv├ílida: o primeiro registo do dia deve ser entrada.'
          USING ERRCODE = '23514';
      END IF;
      v_last := v_t;
      CONTINUE;
    END IF;

    IF v_last = 'entrada' THEN
      IF v_t IN ('pausa', 'saida') THEN
        v_last := v_t;
        CONTINUE;
      END IF;
      IF v_t = 'entrada' THEN
        RAISE EXCEPTION 'Sequ├¬ncia de ponto inv├ílida: registe intervalo ou sa├¡da antes de uma nova entrada.'
          USING ERRCODE = '23514';
      END IF;
    END IF;

    IF v_last = 'pausa' THEN
      IF v_t = 'entrada' THEN
        v_last := v_t;
        CONTINUE;
      END IF;
      IF v_t = 'pausa' THEN
        RAISE EXCEPTION 'Sequ├¬ncia de ponto inv├ílida: intervalo j├í iniciado. Finalize o intervalo antes de iniciar outro.'
          USING ERRCODE = '23514';
      END IF;
      IF v_t = 'saida' THEN
        RAISE EXCEPTION 'Sequ├¬ncia de ponto inv├ílida: finalize o intervalo (retorno) antes da sa├¡da.'
          USING ERRCODE = '23514';
      END IF;
    END IF;

    IF v_last = 'saida' THEN
      IF v_t = 'entrada' THEN
        v_last := v_t;
        CONTINUE;
      END IF;
      IF v_t = 'saida' THEN
        RAISE EXCEPTION 'Sequ├¬ncia de ponto inv├ílida: registe entrada antes de uma nova sa├¡da.'
          USING ERRCODE = '23514';
      END IF;
      IF v_t = 'pausa' THEN
        RAISE EXCEPTION 'Sequ├¬ncia de ponto inv├ílida: registe entrada antes de iniciar intervalo.'
          USING ERRCODE = '23514';
      END IF;
    END IF;

    v_last := v_t;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.time_records_enforce_punch_sequence() OWNER TO postgres;

--
-- Name: FUNCTION time_records_enforce_punch_sequence(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.time_records_enforce_punch_sequence() IS 'BEFORE INSERT: dupla entrada + reconcilia├º├úo (Portaria); segundo intervalo_saida com intervalo j├í aberto ÔåÆ retorno.';


--
-- Name: timesheet_is_closed_for_stamp(text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.timesheet_is_closed_for_stamp(p_company_id text, p_employee_id text, p_ref_ts timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.timesheet_closures tc
    WHERE tc.company_id::text = btrim(COALESCE(p_company_id, ''))
      AND tc.employee_id::text = btrim(COALESCE(p_employee_id, ''))
      AND tc.month = EXTRACT(MONTH FROM (p_ref_ts AT TIME ZONE 'America/Sao_Paulo'))::INT
      AND tc.year = EXTRACT(YEAR FROM (p_ref_ts AT TIME ZONE 'America/Sao_Paulo'))::INT
  );
$$;


ALTER FUNCTION public.timesheet_is_closed_for_stamp(p_company_id text, p_employee_id text, p_ref_ts timestamp with time zone) OWNER TO postgres;

--
-- Name: trg_append_device_operational_reputation_history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_append_device_operational_reputation_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
      device_key, company_id, employee_id,
      score_before, score_after, signals_before, signals_after, event_kind
    ) VALUES (
      NEW.device_key, NEW.company_id, NEW.employee_id,
      OLD.score, NEW.score, OLD.signals, NEW.signals, 'UPDATE'
    );
  ELSIF TG_OP = 'INSERT' THEN
      device_key, company_id, employee_id,
      score_before, score_after, signals_before, signals_after, event_kind
    ) VALUES (
      NEW.device_key, NEW.company_id, NEW.employee_id,
      NULL, NEW.score, NULL, NEW.signals, 'INSERT'
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_append_device_operational_reputation_history() OWNER TO postgres;

--
-- Name: trg_append_operational_state_history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_append_operational_state_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
BEGIN
  VALUES (
    NEW.company_id,
    NEW.employee_id,
    row_to_json(NEW)::jsonb
  );
  RAISE LOG '[STATE HISTORY APPEND] company=% employee=%', NEW.company_id, NEW.employee_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_append_operational_state_history() OWNER TO postgres;

--
-- Name: trg_cos_before_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_cos_before_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.state_version IS NOT NULL AND OLD.state_version IS NOT NULL AND NEW.state_version < OLD.state_version THEN
      RAISE EXCEPTION '[SQL MONOTONIC BLOCK] state_version regression company=% employee=% old=% new=%',
        OLD.company_id, OLD.employee_id, OLD.state_version, NEW.state_version
        USING ERRCODE = '23514';
    END IF;
    IF NEW.last_event_at IS NOT NULL AND OLD.last_event_at IS NOT NULL AND NEW.last_event_at < OLD.last_event_at THEN
      RAISE EXCEPTION '[SQL MONOTONIC BLOCK] last_event_at regression company=% employee=%',
        OLD.company_id, OLD.employee_id
        USING ERRCODE = '23514';
    END IF;
  END IF;

  NEW.geo_snapshot_checksum := public._compute_geo_snapshot_checksum(
    NEW.map_latitude,
    NEW.map_longitude,
    NEW.map_accuracy,
    NEW.map_captured_at,
    NEW.state_version
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_cos_before_write() OWNER TO postgres;

--
-- Name: FUNCTION trg_cos_before_write(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.trg_cos_before_write() IS 'Bloqueia regress├úo de state_version/last_event_at; define geo_snapshot_checksum.';


