--
-- Name: upsert_daily_timesheet(uuid, text, date, integer, integer, integer, integer, integer, integer, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_daily_timesheet(p_employee_id uuid, p_company_id text, p_date date, p_worked_minutes integer, p_expected_minutes integer DEFAULT 480, p_overtime_minutes integer DEFAULT 0, p_absence_minutes integer DEFAULT 0, p_night_minutes integer DEFAULT 0, p_late_minutes integer DEFAULT 0, p_is_absence boolean DEFAULT false, p_raw_data jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_id UUID;
BEGIN
        employee_id, company_id, date,
        worked_minutes, expected_minutes, overtime_minutes,
        absence_minutes, night_minutes, late_minutes,
        is_absence, raw_data
    ) VALUES (
        p_employee_id, p_company_id, p_date,
        p_worked_minutes, p_expected_minutes, p_overtime_minutes,
        p_absence_minutes, p_night_minutes, p_late_minutes,
        p_is_absence, p_raw_data
    )
    ON CONFLICT (employee_id, date) 
    DO UPDATE SET
        worked_minutes = EXCLUDED.worked_minutes,
        expected_minutes = EXCLUDED.expected_minutes,
        overtime_minutes = EXCLUDED.overtime_minutes,
        absence_minutes = EXCLUDED.absence_minutes,
        night_minutes = EXCLUDED.night_minutes,
        late_minutes = EXCLUDED.late_minutes,
        is_absence = EXCLUDED.is_absence,
        raw_data = EXCLUDED.raw_data,
        updated_at = NOW()
    RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$;


ALTER FUNCTION public.upsert_daily_timesheet(p_employee_id uuid, p_company_id text, p_date date, p_worked_minutes integer, p_expected_minutes integer, p_overtime_minutes integer, p_absence_minutes integer, p_night_minutes integer, p_late_minutes integer, p_is_absence boolean, p_raw_data jsonb) OWNER TO postgres;

