--
-- Name: validate_device_key(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_device_key(p_device_id text, p_api_key text) RETURNS TABLE(valid boolean, company_id text, permissions jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    dk.active AND (dk.expires_at IS NULL OR dk.expires_at > NOW()),
    dk.company_id,
    dk.permissions
  FROM public.device_keys dk
  WHERE dk.device_id = p_device_id
  AND dk.api_key_hash = crypt(p_api_key, dk.api_key_hash)
  LIMIT 1;
END;
$$;


ALTER FUNCTION public.validate_device_key(p_device_id text, p_api_key text) OWNER TO postgres;

--
-- Name: validate_employee_schedule_shift_links(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_employee_schedule_shift_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_company_id text;
  v_link_company_id text;
BEGIN
  v_company_id := NULLIF(NEW.company_id::text, '');

  IF NEW.schedule_id IS NOT NULL THEN
    SELECT NULLIF(s.company_id::text, '')
    INTO v_link_company_id
    FROM public.schedules s
    WHERE s.id = NEW.schedule_id
    LIMIT 1;

    IF v_link_company_id IS NULL THEN
      RAISE EXCEPTION 'schedule_id % n├úo pertence a uma empresa v├ílida', NEW.schedule_id
        USING ERRCODE = '23514';
    END IF;

    IF v_company_id IS NOT NULL AND v_link_company_id IS DISTINCT FROM v_company_id THEN
      RAISE EXCEPTION 'schedule_id % pertence ao company_id %, n├úo ao company_id %',
        NEW.schedule_id, v_link_company_id, v_company_id
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.shift_id IS NOT NULL THEN
    SELECT NULLIF(ws.company_id::text, '')
    INTO v_link_company_id
    FROM public.work_shifts ws
    WHERE ws.id = NEW.shift_id
    LIMIT 1;

    IF v_link_company_id IS NULL THEN
      RAISE EXCEPTION 'shift_id % n├úo pertence a uma empresa v├ílida', NEW.shift_id
        USING ERRCODE = '23514';
    END IF;

    IF v_company_id IS NOT NULL AND v_link_company_id IS DISTINCT FROM v_company_id THEN
      RAISE EXCEPTION 'shift_id % pertence ao company_id %, n├úo ao company_id %',
        NEW.shift_id, v_link_company_id, v_company_id
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_employee_schedule_shift_links() OWNER TO postgres;

--
-- Name: validate_employee_shift_schedule_tenant(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_employee_shift_schedule_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_company_id text;
  v_employee_company_id text;
  v_shift_company_id text;
BEGIN
  v_company_id := NULLIF(NEW.company_id::text, '');

  IF NEW.shift_id IS NOT NULL
     AND NEW.work_shift_id IS NOT NULL
     AND NEW.shift_id IS DISTINCT FROM NEW.work_shift_id THEN
    RAISE EXCEPTION 'shift_id % e work_shift_id % devem apontar para o mesmo hor├írio',
      NEW.shift_id, NEW.work_shift_id
      USING ERRCODE = '23514';
  END IF;

  SELECT NULLIF(u.company_id::text, '')
  INTO v_employee_company_id
  FROM public.users u
  WHERE u.id = NEW.employee_id
  LIMIT 1;

  IF v_company_id IS NOT NULL
     AND v_employee_company_id IS NOT NULL
     AND v_employee_company_id IS DISTINCT FROM v_company_id THEN
    RAISE EXCEPTION 'employee_id % pertence ao company_id %, n├úo ao company_id %',
      NEW.employee_id, v_employee_company_id, v_company_id
      USING ERRCODE = '23514';
  END IF;

  IF COALESCE(NEW.shift_id, NEW.work_shift_id) IS NOT NULL THEN
    SELECT NULLIF(ws.company_id::text, '')
    INTO v_shift_company_id
    FROM public.work_shifts ws
    WHERE ws.id = COALESCE(NEW.shift_id, NEW.work_shift_id)
    LIMIT 1;

    IF v_shift_company_id IS NULL THEN
      RAISE EXCEPTION 'hor├írio % n├úo pertence a uma empresa v├ílida',
        COALESCE(NEW.shift_id, NEW.work_shift_id)
        USING ERRCODE = '23514';
    END IF;

    IF v_company_id IS NOT NULL AND v_shift_company_id IS DISTINCT FROM v_company_id THEN
      RAISE EXCEPTION 'hor├írio % pertence ao company_id %, n├úo ao company_id %',
        COALESCE(NEW.shift_id, NEW.work_shift_id), v_shift_company_id, v_company_id
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_employee_shift_schedule_tenant() OWNER TO postgres;

--
-- Name: work_shifts_before_save(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.work_shifts_before_save() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Calcular carga hor├íria
  NEW.carga_horaria_minutos := public.calcular_carga_horaria_minutos(
    NEW.start_time,
    NEW.end_time,
    NEW.break_start_time,
    NEW.break_end_time
  );
  
  -- Detectar turno noturno (sa├¡da < entrada significa que passa da meia-noite)
  NEW.is_night_shift := (NEW.end_time < NEW.start_time);
  
  -- Manter compatibilidade com night_shift existente
  IF NEW.is_night_shift THEN
    NEW.night_shift := true;
  END IF;
  
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.work_shifts_before_save() OWNER TO postgres;

