--
-- Name: company_audit_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.company_audit_summary AS
 SELECT company_id,
    date("timestamp") AS date,
    action,
    count(*) AS count,
    count(*) FILTER (WHERE (severity = 'critical'::text)) AS critical_count
   FROM public.audit_log
  WHERE ("timestamp" > (now() - '30 days'::interval))
  GROUP BY company_id, (date("timestamp")), action;


ALTER VIEW public.company_audit_summary OWNER TO postgres;

