--
-- Name: multi_tenant_audit_report; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.multi_tenant_audit_report AS
 WITH critical(table_name) AS (
         VALUES ('employees'::text), ('departments'::text), ('schedules'::text), ('estruturas'::text), ('time_records'::text), ('time_entries'::text), ('time_balance'::text), ('bank_hours'::text), ('bank_hours_ledger'::text), ('requests'::text), ('notifications'::text), ('holidays'::text), ('feriados'::text), ('work_shifts'::text), ('colaborador_jornada'::text), ('time_adjustments'::text), ('audit_logs'::text), ('employees_documents'::text), ('employees_contracts'::text), ('global_settings'::text), ('company_rules'::text)
        ), cols AS (
         SELECT columns.table_name,
            bool_or(((columns.column_name)::name = 'company_id'::name)) AS has_company_id,
            bool_or((((columns.column_name)::name = 'company_id'::name) AND ((columns.is_nullable)::text = 'NO'::text))) AS company_id_not_null
           FROM information_schema.columns
          WHERE ((columns.table_schema)::name = 'public'::name)
          GROUP BY columns.table_name
        ), idx AS (
         SELECT t.relname AS table_name,
            bool_or((pg_get_indexdef(i.indexrelid) ~~* '%company_id%'::text)) AS company_id_indexed
           FROM ((pg_class t
             JOIN pg_namespace n ON ((n.oid = t.relnamespace)))
             LEFT JOIN pg_index i ON ((i.indrelid = t.oid)))
          WHERE (n.nspname = 'public'::name)
          GROUP BY t.relname
        )
 SELECT c.table_name,
    (to_regclass(('public.'::text || c.table_name)) IS NOT NULL) AS table_exists,
    COALESCE(cols.has_company_id, (c.table_name = 'time_entries'::text)) AS has_company_id,
    COALESCE(idx.company_id_indexed, false) AS company_id_indexed,
    COALESCE(cols.company_id_not_null, false) AS company_id_not_null,
        CASE
            WHEN (c.table_name = 'time_entries'::text) THEN 'view: derived from time_records'::text
            WHEN (to_regclass(('public.'::text || c.table_name)) IS NULL) THEN 'missing_table'::text
            WHEN (COALESCE(cols.has_company_id, false) IS FALSE) THEN 'missing_company_id'::text
            WHEN (COALESCE(idx.company_id_indexed, false) IS FALSE) THEN 'missing_company_index'::text
            WHEN (COALESCE(cols.company_id_not_null, false) IS FALSE) THEN 'company_id_guard_not_validated_or_nullable'::text
            ELSE 'ok'::text
        END AS status
   FROM ((critical c
     LEFT JOIN cols ON (((cols.table_name)::name = c.table_name)))
     LEFT JOIN idx ON ((idx.table_name = c.table_name)))
  ORDER BY c.table_name;


ALTER VIEW public.multi_tenant_audit_report OWNER TO postgres;

