-- Name: suspicious_login_attempts; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.suspicious_login_attempts AS
 SELECT identifier,
    ip_address,
    attempt_count,
    first_attempt_at,
    last_attempt_at,
    locked_until
   FROM public.login_attempts
  WHERE ((attempt_count >= 3) AND (last_attempt_at > (now() - '01:00:00'::interval)))
  ORDER BY attempt_count DESC, last_attempt_at DESC;


