--
-- Name: v_rep_punch_logs_pendentes_espelho; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_rep_punch_logs_pendentes_espelho AS
 SELECT id,
    company_id,
    rep_device_id,
    data_hora,
    tipo_marcacao,
    nsr,
    pis,
    cpf,
    matricula,
    nome_funcionario,
    time_record_id,
    created_at,
    (EXISTS ( SELECT 1
           FROM public.users u
          WHERE ((u.company_id = l.company_id) AND (((public.rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)) IS NOT NULL) AND (public.rep_afd_canonical_11_digits(COALESCE(u.pis_pasep, ''::text)) = public.rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)))) OR ((public.rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)) IS NOT NULL) AND public.rep_matricula_matches_user_fields(public.rep_afd_canonical_11_digits(COALESCE(l.pis, ''::text)), u.numero_folha, u.numero_identificador)) OR public.rep_matricula_matches_user_fields(COALESCE(NULLIF(TRIM(BOTH FROM l.matricula), ''::text), public.rep_derive_matricula_from_afd_11(COALESCE(l.pis, l.cpf, ''::text))), u.numero_folha, u.numero_identificador) OR ((public.rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)) IS NOT NULL) AND (public.rep_afd_canonical_11_digits(COALESCE(u.cpf, ''::text)) = public.rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)))) OR ((public.rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)) IS NOT NULL) AND public.rep_matricula_matches_user_fields(public.rep_afd_canonical_11_digits(COALESCE(l.cpf, ''::text)), u.numero_folha, u.numero_identificador)))))) AS cadastro_compativel
   FROM public.rep_punch_logs l
  WHERE (time_record_id IS NULL);


ALTER VIEW public.v_rep_punch_logs_pendentes_espelho OWNER TO postgres;

