--
-- Name: vw_escalas_completas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_escalas_completas AS
 SELECT s.id,
    s.company_id,
    s.name AS nome,
    s.tipo,
    s.dias_trabalho,
    s.dias_folga,
    s.descricao,
    s.days AS dias_semana,
    s.shift_id AS horario_padrao_id,
    ws.name AS horario_padrao_nome,
    s.ativo,
    s.created_at,
    s.updated_at,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('dia_semana', ed.dia_semana, 'tipo', ed.tipo, 'horario_id', ed.horario_id, 'horario_nome', wsd.name) ORDER BY ed.dia_semana) AS jsonb_agg
           FROM (public.escala_dias ed
             LEFT JOIN public.work_shifts wsd ON ((wsd.id = ed.horario_id)))
          WHERE (ed.escala_id = s.id)), '[]'::jsonb) AS dias_detalhados
   FROM (public.schedules s
     LEFT JOIN public.work_shifts ws ON ((ws.id = s.shift_id)))
  WHERE ((s.ativo = true) OR (s.ativo IS NULL));


ALTER VIEW public.vw_escalas_completas OWNER TO postgres;

--
-- Name: vw_horarios_completos; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_horarios_completos AS
 SELECT id,
    company_id,
    number AS numero,
    name AS nome,
    description AS descricao,
    start_time AS hora_entrada,
    end_time AS hora_saida,
    break_start_time AS intervalo_inicio,
    break_end_time AS intervalo_fim,
    break_duration,
    break_minutes,
    tolerance_minutes,
    tolerancia_entrada,
    tolerancia_saida,
    carga_horaria_minutos,
    concat(lpad(((carga_horaria_minutos / 60))::text, 2, '0'::text), ':', lpad(((carga_horaria_minutos % 60))::text, 2, '0'::text)) AS carga_horaria_formatada,
    shift_type AS tipo_jornada,
    is_night_shift AS turno_noturno,
    ativo,
    config,
    created_at,
    updated_at
   FROM public.work_shifts ws
  WHERE ((ativo = true) OR (ativo IS NULL));


ALTER VIEW public.vw_horarios_completos OWNER TO postgres;

--
-- Name: work_locations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.work_locations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    name text NOT NULL,
    latitude numeric NOT NULL,
    longitude numeric NOT NULL,
    radius numeric DEFAULT 200 NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    tenant_id uuid GENERATED ALWAYS AS (company_id) STORED,
    radius_meters integer
);


ALTER TABLE public.work_locations OWNER TO postgres;

--
-- Name: work_schedules; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.work_schedules AS
 SELECT s.id,
    s.company_id,
    s.name,
    COALESCE((ws.start_time)::text, '08:00'::text) AS start_time,
    COALESCE((ws.end_time)::text, '17:00'::text) AS end_time,
    COALESCE((ws.break_start_time)::text, (ws.start_time)::text) AS break_start,
    COALESCE((ws.break_end_time)::text, (ws.end_time)::text) AS break_end,
    COALESCE(ws.tolerance_minutes, 0) AS tolerance_minutes,
    COALESCE(((EXTRACT(epoch FROM (ws.end_time - ws.start_time)) / 3600.0) -
        CASE
            WHEN ((ws.break_start_time IS NOT NULL) AND (ws.break_end_time IS NOT NULL)) THEN (EXTRACT(epoch FROM (ws.break_end_time - ws.break_start_time)) / 3600.0)
            ELSE (0)::numeric
        END), (8)::numeric) AS daily_hours,
    ( SELECT (count(*))::integer AS count
           FROM unnest(COALESCE(s.days, ARRAY[]::integer[])) d(d)
          WHERE ((d.d >= 1) AND (d.d <= 7))) AS work_days_count
   FROM (public.schedules s
     LEFT JOIN public.work_shifts ws ON ((ws.id = s.shift_id)));


ALTER VIEW public.work_schedules OWNER TO postgres;

